            background-color: #28a745;
        }
    </style>
</head>
<body>

    <div class="container">
        <h2>Song Analysis Data</h2>

        <!-- Read-only Textarea -->
        <textarea id="analysisData" readonly>
Song Title: Midnight City
BPM: 105
Key: B Minor
Genre: Synth-pop
Mood: Nostalgic, Energetic

Analysis:
The track features a driving beat characterized by heavy reverb and synthesizers. The vocal hook is high-pitched and processed. Dynamics remain consistent throughout with a crescendo in the bridge.
        </textarea>

        <!-- Copy Button -->
        <button id="copyBtn" onclick="copyToClipboard()">Copy Analysis to Clipboard</button>
    </div>

    <script>
        function copyToClipboard() {
            // 1. Select the text area element
            const copyText = document.getElementById("analysisData");
            const copyButton = document.getElementById("copyBtn");

            // 2. Select the text field visually (optional, for user experience)
            copyText.select();
            copyText.setSelectionRange(0, 99999); // For mobile devices

            // 3. Copy the text inside the text field using the modern Clipboard API
            navigator.clipboard.writeText(copyText.value)
                .then(() => {
                    // --- SUCCESS FEEDBACK ---

                    // Change button text
                    const originalText = copyButton.innerText;
                    copyButton.innerText = "Copied Successfully! ✓";

                    // Add success class for color change
                    copyButton.classList.add("success");

                    // Revert button back to normal after 2 seconds
                    setTimeout(() => {
                        copyButton.innerText = originalText;
                        copyButton.classList.remove("success");
                        // Optional: Deselect text after copying
                        window.getSelection().removeAllRanges();
                    }, 2000);
                })
                .catch(err => {
                    console.error('Failed to copy: ', err);
                    alert("Failed to copy text. Please try manually.");
                });
        }
    </script>

</body>
</html>

