import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, Wand2, AlertCircle, FileAudio, RotateCcw, ArrowUpCircle, Music, Gauge, Mic2, Sparkles, MoveRight, Loader2, CheckCircle2, FileText, Copy, Check } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string; // e.g. "To High Valence (Joy)"
  weights: string; // e.g. "V: +0.8, A: +0.6"
  advice: string;
}

interface AnalysisResponse {
  segments: AudioSegment[];
  trackInfo: TrackInfo;
  suggestions: ShiftSuggestion[];
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  // Use full emotion state to drive visualizations
  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);

  const activeSegmentIndexRef = useRef<number>(-1);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;

    if (wavesurfer.current) {
      wavesurfer.current.destroy();
    }

    wsRegions.current = RegionsPlugin.create();

    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(255, 255, 255, 0.1)',
      progressColor: 'rgba(56, 189, 248, 0.4)',
      cursorColor: '#ffffff',
      barWidth: 2,
      barGap: 3,
      height: 60, // Reduced height as it's an overlay now
      plugins: [wsRegions.current],
    });

    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => {
      setCurrentTime(t);
    });
    wavesurfer.current.on('finish', () => setIsPlaying(false));

    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });

    return () => {
      wavesurfer.current?.destroy();
    };
  }, [audioUrl]); 

  // Sync Logic: Update Emotion based on playback
  useEffect(() => {
    if (!segments.length) return;

    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });

    // Update if changed
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];

      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);

      // Update External Components
      if (onSegmentSelect) {
        onSegmentSelect(newEmotion);
      }
    }
  }, [currentTime, segments, onSegmentSelect]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("File is too large. Please upload an audio file under 150MB.");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);

      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      setCurrentEmotion(null);
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;

    const exportData = {
      trackInfo,
      segments,
      suggestions
    };

    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error("Failed to copy", err);
    }
  };

  const togglePlay = () => {
    if (wavesurfer.current) wavesurfer.current.playPause();
  };

  const bufferToWav = (buffer: AudioBuffer): Blob => {
    const numOfChan = 1; 
    const length = buffer.length * numOfChan * 2 + 44;
    const bufferArr = new ArrayBuffer(length);
    const view = new DataView(bufferArr);
    const channels = [];
    let i;
    let sample;
    let offset = 0;
    let pos = 0;

    for (i = 0; i < numOfChan; i++) channels.push(buffer.getChannelData(i));

    setUint32(0x46464952); setUint32(length - 8); setUint32(0x45564157); setUint32(0x20746d66); 
    setUint32(16); setUint16(1); setUint16(numOfChan); setUint32(buffer.sampleRate);
    setUint32(buffer.sampleRate * 2 * numOfChan); setUint16(numOfChan * 2); setUint16(16); 
    setUint32(0x61746164); setUint32(length - pos - 4); 

    while (pos < buffer.length) {
      for (i = 0; i < numOfChan; i++) {
        sample = Math.max(-1, Math.min(1, channels[i][pos])); 
        sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
        view.setInt16(44 + offset, sample, true);
        offset += 2;
      }
      pos++;
    }
    function setUint16(data: any) { view.setUint16(pos, data, true); pos += 2; }
    function setUint32(data: any) { view.setUint32(pos, data, true); pos += 4; }
    return new Blob([bufferArr], { type: 'audio/wav' });
  };

  const processAudioForAi = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
    if (file.size < 4 * 1024 * 1024) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: file.type }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
    }

    try {
      const arrayBuffer = await file.arrayBuffer();
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      const targetSampleRate = 22050; 
      const offlineCtx = new OfflineAudioContext(1, audioBuffer.duration * targetSampleRate, targetSampleRate);
      const source = offlineCtx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(offlineCtx.destination);
      source.start();
      const resampledBuffer = await offlineCtx.startRendering();
      const wavBlob = bufferToWav(resampledBuffer);

      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: 'audio/wav' }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(wavBlob);
      });
    } catch (e) {
      throw new Error("Could not process audio file.");
    }
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Stage 1: Audio Optimization
      const audioPart = await processAudioForAi(audioFile);

      // Stage 2: Track Info (Key, Tempo, Chords)
      setAnalysisStep('analyzing_key');
      const trackPrompt = `
        Analyze this audio file (Mono/22kHz).
        Identify the Global Musical Key, Tempo (BPM), and main Chord Progression.
        Return strictly valid JSON:
        { "trackInfo": { "key": "string", "tempo": "string", "chords": "string" } }
      `;

      const trackResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { role: 'user', parts: [audioPart, { text: trackPrompt }] }
      });

      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) {
        console.warn("Failed to parse track info JSON", e);
      }

      // Stage 3: Segments & Suggestions
      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `
        Analyze this audio using the DEAM (Database for Emotional Analysis in Music) dataset principles.
        ${scriptContext ? `\nCONTEXT/SCRIPT PROVIDED BY USER: "${scriptContext}"\nUse this context to accurately align emotional shifts and audio events.` : ''}

        Tasks:
        1. Break the song into distinct emotional sections based on auditory changes.
        2. Assign a Valence (Positivity) and Arousal (Energy) score (-1.0 to 1.0) for each.
        3. In the 'description' field, describe the texture, timbre, and dynamics as if describing it to someone who cannot hear. 
           CRITICAL: You MUST explicitly mention the Valence (V) and Arousal (A) values in the text description and explain why the physics of the sound creates that feeling (e.g., "Fast, chaotic drums increase Arousal to 0.9...").
        4. Provide 3 remix suggestions.

        Return strictly valid JSON:
        {
          "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }],
          "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }]
        }
      `;

      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { role: 'user', parts: [audioPart, { text: segmentPrompt }] }
      });

      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);

      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);

      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});

        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);

        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.2)`, drag: false, resize: false,
        });
      });

    } catch (err: any) {
      console.error(err);
      setError("Analysis failed. " + (err.message || "Unknown error"));
    } finally {
      setAnalysisStep('idle');
    }
  };

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const isComplete = (step: AnalysisStep, target: AnalysisStep) => {
    const order = ['idle', 'optimizing', 'analyzing_key', 'analyzing_segments'];
    if (segments.length > 0 && step === 'idle') return true;
    if (step === 'idle') return false; 
    const currentIndex = order.indexOf(step);
    const targetIndex = order.indexOf(target);
    return currentIndex > targetIndex;
  };

  const isActive = (step: AnalysisStep, target: AnalysisStep) => step === target;

  const activeKeyData = currentEmotion ? getNearestKey(currentEmotion) : null;
  const primaryColor = activeKeyData ? activeKeyData.primaryColor : '#38bdf8';
  const secondaryColor = activeKeyData ? activeKeyData.secondaryColor : '#818cf8';

  return (
    <div className="w-full p-4 md:p-8 max-w-7xl mx-auto text-gray-100">
       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          <div className="lg:col-span-4 space-y-6">
             <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                   <FileAudio className="w-5 h-5 text-primary" />
                   Upload Source
                </h3>

                <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center hover:bg-gray-800/50 transition-colors cursor-pointer relative">
                   <input type="file" accept="audio/*" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                   <Upload className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                   <p className="text-sm text-gray-300">{audioFile ? audioFile.name : "Click to upload .wav or .mp3"}</p>
                   <p className="text-xs text-gray-500 mt-1">Max 150MB</p>
                </div>

                {/* Script Context Input */}
                <div className="mt-4">
                  <label className="flex items-center gap-2 text-xs text-gray-400 font-semibold uppercase tracking-wider mb-2">
                    <FileText className="w-3 h-3" /> Script / Context (Optional)
                  </label>
                  <textarea
                    className="w-full bg-slate-900/50 border border-gray-600 rounded-lg p-3 text-sm text-gray-200 placeholder-gray-500 focus:outline-none focus:border-primary transition-colors resize-none h-24"
                    placeholder="Paste lyrics, scene description, or specific cues here to help the AI align its analysis..."
                    value={scriptContext}
                    onChange={(e) => setScriptContext(e.target.value)}
                  />
                </div>

                {error && (
                  <div className="mt-4 p-3 bg-red-900/20 border border-red-800 rounded-lg flex items-start gap-2">
                    <AlertCircle className="w-4 h-4 text-red-400 mt-0.5" />
                    <p className="text-xs text-red-200">{error}</p>
                  </div>
                )}

                <div className="mt-6 flex gap-2">
                   <button onClick={togglePlay} disabled={!audioFile} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-colors">
                      {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />} {isPlaying ? "Pause" : "Play"}
                   </button>
                   <button onClick={analyzeAudio} disabled={!audioFile || analysisStep !== 'idle'} className="flex-1 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all shadow-lg shadow-purple-900/20">
                      {analysisStep !== 'idle' ? <RotateCcw className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />} 
                      {analysisStep !== 'idle' ? "Processing..." : "Analyze Track"}
                   </button>
                </div>
             </div>

             {/* Info Card */}
             {segments.length > 0 && (
               <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                  <h4 className="text-sm font-semibold mb-3 text-gray-400 uppercase tracking-wider">Visualizer</h4>
                  <div className="flex flex-col gap-2 text-xs text-gray-400">
                     <p>Real-time FFT audio spectrum analysis with emotion-driven coloring.</p>
                  </div>
               </div>
             )}

             {/* Data Export Card */}
             {segments.length > 0 && (
               <div className="bg-surface rounded-2xl p-6 border border-gray-700 animate-in fade-in slide-in-from-left-4 duration-500 delay-100">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                       <FileText className="w-4 h-4" /> Data Export
                    </h3>
                    <button 
                      onClick={handleCopyData}
                      className={`
                        flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all
                        ${copySuccess 
                          ? 'bg-green-500/20 text-green-400 border border-green-500/50' 
                          : 'bg-gray-800 text-gray-300 hover:bg-gray-700 border border-gray-600'}
                      `}
                    >
                      {copySuccess ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                      {copySuccess ? 'Copied!' : 'Copy JSON'}
                    </button>
                  </div>

                  <div className="relative group">
                    <div className="absolute inset-0 bg-gradient-to-b from-transparent to-surface/10 pointer-events-none" />
                    <textarea 
                      readOnly 
                      value={JSON.stringify({ trackInfo, segments, suggestions }, null, 2)}
                      className="w-full h-48 bg-slate-950/50 border border-gray-700 rounded-lg p-3 text-[10px] font-mono text-gray-500 resize-none focus:outline-none focus:border-gray-600 transition-colors"
                    />
                  </div>
                  <p className="text-xs text-gray-500 mt-2">
                    Contains full track info, emotional segments, and remix suggestions.
                  </p>
               </div>
             )}
          </div>

          <div className="lg:col-span-8 space-y-6">
             <audio ref={audioRef} src={audioUrl || undefined} crossOrigin="anonymous" className="hidden" />

             {trackInfo && (
                <div className="bg-gradient-to-r from-slate-800 to-slate-900 border border-slate-700 rounded-2xl p-6 shadow-lg animate-in fade-in slide-in-from-top-4 duration-700">
                  <div className="flex flex-col md:flex-row md:items-center gap-6 border-b border-gray-700 pb-6 mb-6">
                    <div className="flex items-center gap-4 flex-1">
                       <div className="p-3 bg-purple-500/20 rounded-xl"><Music className="w-6 h-6 text-purple-400" /></div>
                       <div>
                          <div className="text-xs text-gray-400 uppercase tracking-wide font-bold">Musical Key</div>
                          <div className="text-2xl font-bold text-white tracking-tight">{trackInfo.key}</div>
                       </div>
                    </div>
                    <div className="w-px h-12 bg-gray-700 hidden md:block"></div>
                    <div className="flex items-center gap-4 flex-1">
                       <div className="p-3 bg-blue-500/20 rounded-xl"><Gauge className="w-6 h-6 text-blue-400" /></div>
                       <div>
                          <div className="text-xs text-gray-400 uppercase tracking-wide font-bold">Tempo (BPM)</div>
                          <div className="text-2xl font-bold text-white tracking-tight">{trackInfo.tempo}</div>
                       </div>
                    </div>
                  </div>
                  <div className="w-full">
                     <div className="flex items-start gap-4">
                       <div className="p-3 bg-pink-500/20 rounded-xl mt-1"><Mic2 className="w-6 h-6 text-pink-400" /></div>
                       <div className="flex-1 min-w-0">
                          <div className="text-xs text-gray-400 uppercase tracking-wide font-bold mb-2">Chord Progression</div>
                          <div className="text-lg font-mono text-white bg-slate-950/50 p-4 rounded-lg border border-slate-700/50 break-words leading-relaxed">
                            {trackInfo.chords}
                          </div>
                       </div>
                     </div>
                  </div>
                </div>
             )}

             {/* Live Audio Visualizer */}
             <div className="bg-slate-900/80 border border-gray-700 rounded-2xl p-6 relative overflow-hidden h-[400px]">
                <LiveVisualizer 
                  mediaElement={audioRef.current} 
                  isPlaying={isPlaying} 
                  primaryColor={primaryColor}
                  secondaryColor={secondaryColor}
                />

                <div className="relative z-10 flex flex-col h-full justify-end pointer-events-none">
                  <div className="absolute top-0 right-0 text-sm font-mono text-primary font-bold bg-slate-900/50 px-2 py-1 rounded backdrop-blur">
                     {formatTime(currentTime)}
                  </div>
                  <div id="waveform" ref={containerRef} className="w-full pointer-events-auto"></div>
                  {!audioFile && (
                     <div className="absolute inset-0 flex items-center justify-center text-gray-500 pointer-events-none mb-10">
                        Upload audio to initialize the Visualizer
                     </div>
                  )}
                </div>
             </div>

             <div className="space-y-4">
                <div className="flex items-center justify-between">
                   <h3 className="text-xl font-bold text-white">Detected Segments</h3>
                   {analysisStep !== 'idle' && (
                     <div className="flex items-center gap-2 text-xs text-blue-400 bg-blue-900/20 px-3 py-1 rounded-full animate-pulse">
                        <Loader2 className="w-3 h-3 animate-spin" />
                        Analysis in progress...
                     </div>
                   )}
                </div>

                {/* Progress UI */}
                {analysisStep !== 'idle' && segments.length === 0 && (
                  <div className="bg-surface border border-gray-700 rounded-xl p-6 space-y-6">
                    <div className={`flex items-center gap-4 ${isComplete(analysisStep, 'optimizing') ? 'text-green-400' : isActive(analysisStep, 'optimizing') ? 'text-blue-400' : 'text-gray-600'}`}>
                      {isComplete(analysisStep, 'optimizing') ? <CheckCircle2 className="w-6 h-6" /> : isActive(analysisStep, 'optimizing') ? <Loader2 className="w-6 h-6 animate-spin" /> : <div className="w-6 h-6 rounded-full border-2 border-gray-700" />}
                      <div className="flex-1">
                        <h4 className="font-semibold">Audio Optimization</h4>
                        <p className="text-xs opacity-70">Resampling to 22kHz Mono for AI processing</p>
                      </div>
                    </div>

                    <div className={`flex items-center gap-4 ${isComplete(analysisStep, 'analyzing_key') ? 'text-green-400' : isActive(analysisStep, 'analyzing_key') ? 'text-blue-400' : 'text-gray-600'}`}>
                       {isComplete(analysisStep, 'analyzing_key') ? <CheckCircle2 className="w-6 h-6" /> : isActive(analysisStep, 'analyzing_key') ? <Loader2 className="w-6 h-6 animate-spin" /> : <div className="w-6 h-6 rounded-full border-2 border-gray-700" />}
                       <div className="flex-1">
                        <h4 className="font-semibold">Key & Harmony Detection</h4>
                        <p className="text-xs opacity-70">Identifying global Tempo, Key, and Chords</p>
                      </div>
                    </div>

                    <div className={`flex items-center gap-4 ${isActive(analysisStep, 'analyzing_segments') ? 'text-blue-400' : 'text-gray-600'}`}>
                       {isActive(analysisStep, 'analyzing_segments') ? <Loader2 className="w-6 h-6 animate-spin" /> : <div className="w-6 h-6 rounded-full border-2 border-gray-700" />}
                       <div className="flex-1">
                        <h4 className="font-semibold">Emotional Segmentation</h4>
                        <p className="text-xs opacity-70">Annotating Valence & Arousal shifts via DEAM logic</p>
                      </div>
                    </div>
                  </div>
                )}

                {segments.length > 0 ? (
                  <div className="grid gap-3 animate-in fade-in slide-in-from-bottom-4 duration-700">
                     {segments.map((seg, idx) => {
                       const start = parseTime(seg.startTime);
                       const end = parseTime(seg.endTime);
                       const isActive = currentTime >= start && currentTime < end && isPlaying;
                       const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});

                       return (
                        <div 
                          key={idx} 
                          className={`border p-4 rounded-xl transition-all cursor-pointer group flex flex-col md:flex-row gap-4 items-start md:items-center relative overflow-hidden ${isActive ? 'bg-blue-900/20 border-blue-500' : 'bg-surface border-gray-700 hover:border-blue-500/50 hover:bg-surface/80'}`}
                          onClick={() => {
                             if (wavesurfer.current) { wavesurfer.current.setTime(start); wavesurfer.current.play(); }
                             if(onSegmentSelect) { onSegmentSelect({ valence: seg.valence, arousal: seg.arousal }); }
                          }}
                        >
                           <div className="absolute left-0 top-0 bottom-0 w-1 transition-all" style={{ backgroundColor: colors.primaryColor }} />
                           <div className="flex-shrink-0 bg-gray-800 rounded px-2 py-1 text-xs font-mono text-gray-300">
                              {seg.startTime} - {seg.endTime}
                           </div>
                           <div className="flex-1">
                              <div className="flex items-center gap-2 mb-1">
                                 <span className="font-bold text-white capitalize">{seg.mood}</span>
                                 <span className="text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400">V: {seg.valence} / A: {seg.arousal}</span>
                              </div>
                              <p className="text-sm text-gray-400 leading-relaxed">{seg.description}</p>
                           </div>
                           {isActive && <div className="flex items-center gap-1 text-xs text-blue-400 font-bold animate-pulse">Now Playing</div>}
                        </div>
                       );
                     })}
                  </div>
                ) : (
                  analysisStep === 'idle' && (
                    <div className="text-center py-10 border border-dashed border-gray-700 rounded-xl text-gray-500">
                      Upload audio and click Analyze to begin.
                    </div>
                  )
                )}
             </div>
          </div>
       </div>
    </div>
  );
};

export default AppThree;

import React, { useEffect, useRef } from 'react';

interface LiveVisualizerProps {
  mediaElement: HTMLMediaElement | null;
  isPlaying: boolean;
  primaryColor: string;
  secondaryColor: string;
}

const LiveVisualizer: React.FC<LiveVisualizerProps> = ({ mediaElement, isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // 1. Setup Audio Context
  useEffect(() => {
    if (!mediaElement) return;

    const initAudio = () => {
      if (!audioContextRef.current) {
        const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContext();
      }

      const ctx = audioContextRef.current;

      if (!analyserRef.current) {
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 2048; 
        analyser.smoothingTimeConstant = 0.85; // Increased smoothing for nicer flower effect
        analyserRef.current = analyser;
      }

      // Check if source already exists for this element to avoid error
      if (!sourceRef.current) {
        try {
          const source = ctx.createMediaElementSource(mediaElement);
          source.connect(analyserRef.current!);
          analyserRef.current!.connect(ctx.destination);
          sourceRef.current = source;
        } catch (err) {
          console.warn("Visualizer connection warning:", err);
        }
      }
    };

    initAudio();
  }, [mediaElement]);

  // 2. Handle Resume
  useEffect(() => {
    const ctx = audioContextRef.current;
    if (ctx && isPlaying && ctx.state === 'suspended') {
      ctx.resume();
    }
  }, [isPlaying]);

  // 3. Animation Loop
  useEffect(() => {
    if (!canvasRef.current || !analyserRef.current) return;

    const canvas = canvasRef.current;
    const canvasCtx = canvas.getContext('2d', { alpha: false }); 
    if (!canvasCtx) return;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.offsetWidth * window.devicePixelRatio;
        canvas.height = parent.offsetHeight * window.devicePixelRatio;
        canvasCtx.scale(window.devicePixelRatio, window.devicePixelRatio);
      }
    };
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const analyser = analyserRef.current;
    const bufferLength = analyser.frequencyBinCount; 
    const freqDataArray = new Uint8Array(bufferLength);

    const renderFrame = () => {
      analyser.getByteFrequencyData(freqDataArray);

      const width = canvas.width / window.devicePixelRatio;
      const height = canvas.height / window.devicePixelRatio;
      const centerX = width / 2;
      const centerY = height / 2;

      // Clear Canvas
      canvasCtx.fillStyle = '#0f172a'; 
      canvasCtx.fillRect(0, 0, width, height);

      // --- Calculate Energy for Pulse ---
      // Use low-mid frequencies for the text pulse
      let sum = 0;
      const pulseBinCount = Math.floor(bufferLength * 0.2); 
      for (let i = 0; i < pulseBinCount; i++) {
        sum += freqDataArray[i];
      }
      const avgEnergy = sum / pulseBinCount;
      const pulseScale = 1 + (avgEnergy / 255) * 0.35; // Scale between 1.0 and 1.35

      // --- Time for animations ---
      const time = Date.now() / 1000;

      // ============================================
      // LAYER 1: Rotating Bloom Spectrum Flower
      // ============================================
      canvasCtx.save();
      canvasCtx.translate(centerX, centerY);

      // Rotate entire flower slowly
      canvasCtx.rotate(time * 0.15);

      // "Lighter" composite mode creates the glowing bloom effect when shapes overlap
      canvasCtx.globalCompositeOperation = 'lighter'; 

      const bars = 90; 
      const step = Math.floor((bufferLength * 0.75) / bars); // Use 75% of freq data
      const baseRadius = Math.min(width, height) * 0.22; 

      for (let i = 0; i < bars; i++) {
        const value = freqDataArray[i * step];
        const percent = value / 255;

        // Dynamic bar height
        const barHeight = percent * (Math.min(width, height) * 0.35);

        // Rainbow Coloring
        // Hue cycles around the circle (i/bars) + shifts over time
        const hue = (i / bars) * 360 + (time * 20); 

        // Fill Style
        canvasCtx.fillStyle = `hsla(${hue}, 100%, 60%, ${0.4 + percent * 0.6})`;

        // Bloom/Glow Shadow
        canvasCtx.shadowBlur = 15;
        canvasCtx.shadowColor = `hsla(${hue}, 100%, 50%, 0.8)`;

        canvasCtx.save();
        canvasCtx.rotate((Math.PI * 2 * i) / bars);

        // Draw the "Petal" (Bar)
        // Note: Using a simple rect here, rotated
        const barWidth = (Math.PI * 2 * baseRadius) / bars * 0.8;

        // Draw outward from radius
        canvasCtx.beginPath();
        // A simple rectangle path
        canvasCtx.rect(-barWidth / 2, baseRadius, barWidth, Math.max(4, barHeight));
        canvasCtx.fill();

        // Optional: Add a small dot at the tip for extra "pollen" effect if loud
        if (percent > 0.8) {
           canvasCtx.beginPath();
           canvasCtx.arc(0, baseRadius + barHeight + 4, 2, 0, Math.PI * 2);
           canvasCtx.fillStyle = '#ffffff';
           canvasCtx.fill();
        }

        canvasCtx.restore();
      }
      canvasCtx.restore();

      // ============================================
      // LAYER 2: Pulsing Rainbow Text
      // ============================================
      canvasCtx.save();
      canvasCtx.translate(centerX, centerY);
      canvasCtx.scale(pulseScale, pulseScale);

      // Font Settings
      const fontSize = Math.min(width, height) * 0.08; // Responsive font size
      canvasCtx.font = `900 ${fontSize}px "Inter", sans-serif`;
      canvasCtx.textAlign = 'center';
      canvasCtx.textBaseline = 'middle';

      // Create Dynamic Rainbow Gradient for Text
      // The gradient moves horizontally over time
      const gradient = canvasCtx.createLinearGradient(-width/4, 0, width/4, 0);
      const shift = (time * 80) % 360;
      gradient.addColorStop(0, `hsl(${shift}, 100%, 70%)`);
      gradient.addColorStop(0.5, `hsl(${(shift + 120) % 360}, 100%, 70%)`);
      gradient.addColorStop(1, `hsl(${(shift + 240) % 360}, 100%, 70%)`);

      canvasCtx.fillStyle = gradient;

      // Text Glow/Shadow
      canvasCtx.shadowBlur = 20;
      canvasCtx.shadowColor = `hsl(${shift}, 100%, 50%)`; // Shadow matches gradient base hue

      // Draw Text
      canvasCtx.fillText("I love you, Delaina", 0, 0);

      canvasCtx.restore();

      animationRef.current = requestAnimationFrame(renderFrame);
    };

    renderFrame();

    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      window.removeEventListener('resize', resizeCanvas);
    };
  }, [mediaElement, isPlaying]);

  return (
    <canvas 
      ref={canvasRef} 
      className="absolute inset-0 w-full h-full rounded-2xl pointer-events-none z-0"
    />
  );
};

export default LiveVisualizer;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, Wand2, AlertCircle, FileAudio, RotateCcw, ArrowUpCircle, Music, Gauge, Mic2, Sparkles, MoveRight, Loader2, CheckCircle2, FileText, Copy, Check } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string; // e.g. "To High Valence (Joy)"
  weights: string; // e.g. "V: +0.8, A: +0.6"
  advice: string;
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  // Use full emotion state to drive visualizations
  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);

  const activeSegmentIndexRef = useRef<number>(-1);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;

    if (wavesurfer.current) {
      wavesurfer.current.destroy();
    }

    wsRegions.current = RegionsPlugin.create();

    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(255, 255, 255, 0.1)',
      progressColor: 'rgba(56, 189, 248, 0.4)',
      cursorColor: '#ffffff',
      barWidth: 2,
      barGap: 3,
      height: 60,
      plugins: [wsRegions.current],
    });

    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => {
      setCurrentTime(t);
    });
    wavesurfer.current.on('finish', () => setIsPlaying(false));

    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });

    return () => {
      wavesurfer.current?.destroy();
    };
  }, [audioUrl]); 

  // Sync Logic: Update Emotion based on playback
  useEffect(() => {
    if (!segments.length) return;

    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });

    // Update if changed
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];

      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);

      // Update External Components
      if (onSegmentSelect) {
        onSegmentSelect(newEmotion);
      }
    }
  }, [currentTime, segments, onSegmentSelect]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("File is too large. Please upload an audio file under 150MB.");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);

      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      setCurrentEmotion(null);
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;

    const exportData = {
      trackInfo,
      segments,
      suggestions
    };

    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error("Failed to copy", err);
    }
  };

  const togglePlay = () => {
    if (wavesurfer.current) wavesurfer.current.playPause();
  };

  const bufferToWav = (buffer: AudioBuffer): Blob => {
    const numOfChan = 1; 
    const length = buffer.length * numOfChan * 2 + 44;
    const bufferArr = new ArrayBuffer(length);
    const view = new DataView(bufferArr);
    const channels = [];
    let i, sample, offset = 0, pos = 0;
    for (i = 0; i < numOfChan; i++) channels.push(buffer.getChannelData(i));
    setUint32(0x46464952); setUint32(length - 8); setUint32(0x45564157); setUint32(0x20746d66); 
    setUint32(16); setUint16(1); setUint16(numOfChan); setUint32(buffer.sampleRate);
    setUint32(buffer.sampleRate * 2 * numOfChan); setUint16(numOfChan * 2); setUint16(16); 
    setUint32(0x61746164); setUint32(length - pos - 4); 
    while (pos < buffer.length) {
      for (i = 0; i < numOfChan; i++) {
        sample = Math.max(-1, Math.min(1, channels[i][pos])); 
        sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
        view.setInt16(44 + offset, sample, true);
        offset += 2;
      }
      pos++;
    }
    function setUint16(data: any) { view.setUint16(pos, data, true); pos += 2; }
    function setUint32(data: any) { view.setUint32(pos, data, true); pos += 4; }
    return new Blob([bufferArr], { type: 'audio/wav' });
  };

  const processAudioForAi = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
    if (file.size < 4 * 1024 * 1024) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: file.type }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
    }

    try {
      const arrayBuffer = await file.arrayBuffer();
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      const targetSampleRate = 22050; 
      const offlineCtx = new OfflineAudioContext(1, audioBuffer.duration * targetSampleRate, targetSampleRate);
      const source = offlineCtx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(offlineCtx.destination);
      source.start();
      const resampledBuffer = await offlineCtx.startRendering();
      const wavBlob = bufferToWav(resampledBuffer);

      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: 'audio/wav' }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(wavBlob);
      });
    } catch (e) {
      throw new Error("Could not process audio file.");
    }
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioPart = await processAudioForAi(audioFile);
      setAnalysisStep('analyzing_key');
      const trackPrompt = `
        Analyze this audio file (Mono/22kHz).
        Identify the Global Musical Key, Tempo (BPM), and main Chord Progression.
        Return strictly valid JSON:
        { "trackInfo": { "key": "string", "tempo": "string", "chords": "string" } }
      `;
      const trackResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { role: 'user', parts: [audioPart, { text: trackPrompt }] }
      });
      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) { console.warn("Failed to parse track info JSON", e); }
      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `
        Analyze this audio using the DEAM (Database for Emotional Analysis in Music) dataset principles.
        ${scriptContext ? `\nCONTEXT/SCRIPT PROVIDED BY USER: "${scriptContext}"\nUse this context to accurately align emotional shifts and audio events.` : ''}
        Tasks:
        1. Break the song into distinct emotional sections.
        2. Assign a Valence (V) and Arousal (A) score (-1.0 to 1.0) for each.
        3. Describe the physics of the sound in 'description'.
        4. Provide 3 remix suggestions.
        Return strictly valid JSON:
        {
          "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }],
          "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }]
        }
      `;
      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { role: 'user', parts: [audioPart, { text: segmentPrompt }] }
      });
      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);
      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);
      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);
        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.2)`, drag: false, resize: false,
        });
      });
    } catch (err: any) {
      console.error(err);
      setError("Analysis failed. " + (err.message || "Unknown error"));
    } finally {
      setAnalysisStep('idle');
    }
  };

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const isComplete = (step: AnalysisStep, target: AnalysisStep) => {
    const order = ['idle', 'optimizing', 'analyzing_key', 'analyzing_segments'];
    if (segments.length > 0 && step === 'idle') return true;
    if (step === 'idle') return false; 
    return order.indexOf(step) > order.indexOf(target);
  };

  const isActive = (step: AnalysisStep, target: AnalysisStep) => step === target;

  return (
    <div className="w-full p-4 md:p-8 max-w-7xl mx-auto text-gray-100">
       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          <div className="lg:col-span-4 space-y-6">
             <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                   <FileAudio className="w-5 h-5 text-primary" />
                   Upload Source
                </h3>
                <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center hover:bg-gray-800/50 transition-colors cursor-pointer relative">
                   <input type="file" accept="audio/*" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                   <Upload className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                   <p className="text-sm text-gray-300">{audioFile ? audioFile.name : "Click to upload .wav or .mp3"}</p>
                </div>
                <div className="mt-4">
                  <label className="flex items-center gap-2 text-xs text-gray-400 font-semibold uppercase tracking-wider mb-2">
                    <FileText className="w-3 h-3" /> Script Context
                  </label>
                  <textarea
                    className="w-full bg-slate-900/50 border border-gray-600 rounded-lg p-3 text-sm text-gray-200 placeholder-gray-500 focus:outline-none focus:border-primary transition-colors resize-none h-24"
                    placeholder="Paste lyrics or scene cues..."
                    value={scriptContext}
                    onChange={(e) => setScriptContext(e.target.value)}
                  />
                </div>
                {error && <div className="mt-4 p-3 bg-red-900/20 border border-red-800 rounded-lg text-xs text-red-200">{error}</div>}
                <div className="mt-6 flex gap-2">
                   <button onClick={togglePlay} disabled={!audioFile} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-colors">
                      {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />} {isPlaying ? "Pause" : "Play"}
                   </button>
                   <button onClick={analyzeAudio} disabled={!audioFile || analysisStep !== 'idle'} className="flex-1 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all shadow-lg">
                      {analysisStep !== 'idle' ? <RotateCcw className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />} Analyze
                   </button>
                </div>
             </div>
             {segments.length > 0 && (
               <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Data Export</h3>
                    <button onClick={handleCopyData} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium ${copySuccess ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 'bg-gray-800 text-gray-300 hover:bg-gray-700'}`}>
                      {copySuccess ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />} Copy
                    </button>
                  </div>
                  <textarea readOnly value={JSON.stringify({ trackInfo, segments, suggestions }, null, 2)} className="w-full h-48 bg-slate-950/50 border border-gray-700 rounded-lg p-3 text-[10px] font-mono text-gray-500 resize-none" />
               </div>
             )}
          </div>

          <div className="lg:col-span-8 space-y-6">
             <audio ref={audioRef} src={audioUrl || undefined} crossOrigin="anonymous" className="hidden" />
             {/* Live Audio Visualizer */}
             <div className="bg-slate-900/80 border border-gray-700 rounded-2xl p-6 relative overflow-hidden h-[500px]">
                <LiveVisualizer 
                  mediaElement={audioRef.current} 
                  isPlaying={isPlaying} 
                  valence={currentEmotion?.valence ?? 0}
                  arousal={currentEmotion?.arousal ?? 0}
                />
                <div className="relative z-10 flex flex-col h-full justify-end pointer-events-none">
                  <div className="absolute top-0 right-0 text-sm font-mono text-primary font-bold bg-slate-900/50 px-2 py-1 rounded backdrop-blur">
                     {formatTime(currentTime)}
                  </div>
                  <div id="waveform" ref={containerRef} className="w-full pointer-events-auto opacity-40"></div>
                </div>
             </div>

             <div className="space-y-4">
                <div className="flex items-center justify-between">
                   <h3 className="text-xl font-bold text-white">Detected Segments</h3>
                   {analysisStep !== 'idle' && <div className="flex items-center gap-2 text-xs text-blue-400 bg-blue-900/20 px-3 py-1 rounded-full animate-pulse"><Loader2 className="w-3 h-3 animate-spin" /> Analyzing...</div>}
                </div>
                {segments.length > 0 ? (
                  <div className="grid gap-3">
                     {segments.map((seg, idx) => {
                       const start = parseTime(seg.startTime);
                       const end = parseTime(seg.endTime);
                       const isActive = currentTime >= start && currentTime < end && isPlaying;
                       const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
