                        <div key={idx} className={`border p-4 rounded-xl transition-all cursor-pointer relative overflow-hidden ${isActive ? 'bg-blue-900/20 border-blue-500' : 'bg-surface border-gray-700'}`} onClick={() => { if (wavesurfer.current) { wavesurfer.current.setTime(start); wavesurfer.current.play(); }}}>
