import React, { useEffect, useRef } from 'react';
import { EMOTIONAL_KEYS } from '../constants';

interface LiveVisualizerProps {
  mediaElement: HTMLMediaElement | null;
  isPlaying: boolean;
  valence: number;
  arousal: number;
}

const LiveVisualizer: React.FC<LiveVisualizerProps> = ({ mediaElement, isPlaying, valence, arousal }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // Audio setup
  useEffect(() => {
    if (!mediaElement) return;
    const initAudio = () => {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      if (!analyserRef.current) {
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 1024;
        analyser.smoothingTimeConstant = 0.8;
        analyserRef.current = analyser;
      }
      if (!sourceRef.current) {
        try {
          sourceRef.current = ctx.createMediaElementSource(mediaElement);
          sourceRef.current.connect(analyserRef.current!);
          analyserRef.current!.connect(ctx.destination);
        } catch (err) { console.warn(err); }
      }
    };
    initAudio();
  }, [mediaElement]);

  useEffect(() => {
    const ctx = audioContextRef.current;
    if (ctx && isPlaying && ctx.state === 'suspended') ctx.resume();
  }, [isPlaying]);

  useEffect(() => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const resize = () => {
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.offsetWidth * window.devicePixelRatio;
        canvas.height = parent.offsetHeight * window.devicePixelRatio;
        ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
      }
    };
    resize();
    window.addEventListener('resize', resize);

    const analyser = analyserRef.current;
    const bufferLength = analyser.frequencyBinCount;
    const freqData = new Uint8Array(bufferLength);
    const timeData = new Uint8Array(bufferLength);

    const render = () => {
      analyser.getByteFrequencyData(freqData);
      analyser.getByteTimeDomainData(timeData);

      const w = canvas.width / window.devicePixelRatio;
      const h = canvas.height / window.devicePixelRatio;
      const cx = w / 2;
      const cy = h / 2;
      const time = Date.now() / 1000;

      // Calculate Bass Energy for Pulse
      let bass = 0;
      for (let i = 0; i < 10; i++) bass += freqData[i];
      bass = bass / 10 / 255; // 0..1

      // Physics: Valence to Angle, Arousal to Radius
      // Equation Layer: theta = 2*pi * (V+1)/2, r = 1+A
      const targetAngle = Math.PI * (valence + 1) - Math.PI / 2;
      const targetRadius = Math.min(w, h) * 0.22 * (1.1 + arousal);
      const rotationSpeed = (0.05 + arousal * 0.1) * (isPlaying ? 1 : 0.2);

      // Clear with slight fade for trails
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, w, h);

      // --- LAYER 1: 12 Emotional Nodes (The Circle) ---
      const orbitRadius = Math.min(w, h) * 0.35;
      EMOTIONAL_KEYS.forEach((node, i) => {
        const theta = -Math.PI/2 + (node.keyPosition - 1) * (Math.PI/6);
        const nx = cx + Math.cos(theta) * orbitRadius;
        const ny = cy + Math.sin(theta) * orbitRadius;

        // Proximity check for node glow
        let angDiff = Math.abs(targetAngle - theta);
        while(angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI*2);
        const isActive = angDiff < 0.5;
        const proximity = Math.max(0, 1 - angDiff);

        // Draw Node
        ctx.beginPath();
        const size = 4 + proximity * 12 + bass * 10;
        ctx.arc(nx, ny, size, 0, Math.PI * 2);

        ctx.shadowBlur = isActive ? 20 + bass * 30 : 0;
        ctx.shadowColor = node.primaryColor;
        ctx.fillStyle = node.primaryColor;
        ctx.globalAlpha = 0.2 + proximity * 0.8;
        ctx.fill();
        ctx.shadowBlur = 0;

        // --- LAYER 2: Harmonic Pentagrams (Fifths) ---
        // Lines connecting node to its neighbors (±1 in circle)
        if (isActive) {
           ctx.beginPath();
           ctx.strokeStyle = node.primaryColor;
           ctx.lineWidth = 1 + proximity * 2;
           ctx.globalAlpha = proximity * 0.3;

           // Left Neighbor (Perfect Fifth)
           const prevIdx = (node.keyPosition - 2 + 12) % 12;
           const pNode = EMOTIONAL_KEYS[prevIdx];
           const pt = -Math.PI/2 + (pNode.keyPosition - 1) * (Math.PI/6);
           ctx.moveTo(nx, ny);
           ctx.lineTo(cx + Math.cos(pt) * orbitRadius, cy + Math.sin(pt) * orbitRadius);

           // Right Neighbor
           const nextIdx = (node.keyPosition) % 12;
           const nNode = EMOTIONAL_KEYS[nextIdx];
           const nt = -Math.PI/2 + (nNode.keyPosition - 1) * (Math.PI/6);
           ctx.lineTo(cx + Math.cos(nt) * orbitRadius, cy + Math.sin(nt) * orbitRadius);
           ctx.stroke();
        }
      });

      // --- LAYER 3: Emotional Particle & Harmonic Vector ---
      const px = cx + Math.cos(targetAngle) * targetRadius;
      const py = cy + Math.sin(targetAngle) * targetRadius;

      // Vector Line
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(px, py);
      ctx.strokeStyle = `hsla(${time * 50 % 360}, 100%, 70%, 0.4)`;
      ctx.setLineDash([5, 5]);
      ctx.stroke();
      ctx.setLineDash([]);

      // Particle Head
      ctx.beginPath();
      ctx.arc(px, py, 10 + bass * 15, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 30;
      ctx.shadowColor = `hsl(${time * 50 % 360}, 100%, 50%)`;
      ctx.globalAlpha = 1;
      ctx.fill();
      ctx.shadowBlur = 0;

      // --- LAYER 4: Central Oscillating Core ---
      // Oscilloscope Ring
      ctx.beginPath();
      const waveRadius = 60 + bass * 20;
      for (let i = 0; i < bufferLength; i++) {
        const angle = (i / bufferLength) * Math.PI * 2 + (time * rotationSpeed);
        const offset = (timeData[i] - 128) * 0.5;
        const r = waveRadius + offset;
        const x = cx + Math.cos(angle) * r;
        const y = cy + Math.sin(angle) * r;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.globalAlpha = 0.5;
      ctx.stroke();

      animationRef.current = requestAnimationFrame(render);
    };

    render();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [isPlaying, valence, arousal]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full rounded-2xl pointer-events-none" />;
};

export default LiveVisualizer;

import React, { useMemo } from 'react';
import * as d3 from 'd3';
import { EmotionalKeyData } from '../types';

interface CircleOfFifthsProps {
  data: EmotionalKeyData[];
  selectedId: number | null;
  hoveredId: number | null;
  onSelect: (id: number) => void;
  onHover: (id: number | null) => void;
}

const CircleOfFifths: React.FC<CircleOfFifthsProps> = ({ data, selectedId, hoveredId, onSelect, onHover }) => {
  const width = 400;
  const height = 400;
  const radius = Math.min(width, height) / 2 - 40;
  const center = { x: width / 2, y: height / 2 };

  // D3 Scales and Layout
  const pie = d3.pie<EmotionalKeyData>()
    .value(1) // Equal slices
    .sort((a, b) => a.keyPosition - b.keyPosition) // Ensure C is top then clockwise
    .startAngle(-Math.PI / 2 + Math.PI / 12) // Rotate so C (index 1) is at top. Each slice is 30deg (PI/6). Center of C slice at -90deg.
    .endAngle(1.5 * Math.PI + Math.PI / 12);

  // Main arc generator for the background of slices
  const arcGenerator = d3.arc<d3.PieArcDatum<EmotionalKeyData>>()
    .innerRadius(radius * 0.55)
    .outerRadius(radius);

  // Specific arc generator for the outer color ring to avoid passing custom radii to the datum
  const colorRingArc = d3.arc<d3.PieArcDatum<EmotionalKeyData>>()
    .innerRadius(radius * 0.92)
    .outerRadius(radius);

  const labelArc = d3.arc<d3.PieArcDatum<EmotionalKeyData>>()
    .innerRadius(radius * 0.75)
    .outerRadius(radius * 0.75);

  const arcs = useMemo(() => pie(data), [data]);

  return (
    <div className="flex justify-center items-center relative select-none">
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="drop-shadow-2xl">
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="5" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
        <g transform={`translate(${center.x},${center.y})`}>
          {/* Central Label */}
          <circle r={radius * 0.5} className="fill-surface/80 stroke-gray-700 stroke-2" />
          <text textAnchor="middle" dy="0.3em" className="fill-gray-400 text-sm font-light tracking-widest pointer-events-none">
             THE CIRCLE
          </text>

          {/* Slices */}
          {arcs.map((slice) => {
            // Logic determines which slice is visually "active"
            const isHovered = hoveredId === slice.data.id;
            const isSelected = selectedId === slice.data.id;

            // If user is hovering something, that thing is active.
            // If user is NOT hovering anything, the selected thing is active.
            const isActive = isHovered || (hoveredId === null && isSelected);

            // Everything else is dimmed if there is an active state in play
            const isDimmed = (hoveredId !== null || selectedId !== null) && !isActive;

            const [centroidX, centroidY] = labelArc.centroid(slice);

            return (
              <g 
                key={slice.data.id} 
                onClick={() => onSelect(slice.data.id)}
                onMouseEnter={() => onHover(slice.data.id)}
                onMouseLeave={() => onHover(null)}
                className="cursor-pointer transition-all duration-300 group"
                style={{ opacity: isDimmed ? 0.3 : 1 }}
              >
                <path
                  d={arcGenerator(slice) || undefined}
                  className={`
                    transition-all duration-300 stroke-surface stroke-[2px]
                    ${isActive ? 'fill-gray-100 scale-105' : 'fill-gray-800 hover:fill-gray-700'}
                  `}
                  transform={isActive ? `scale(1.05)` : ''}
                />

                {/* Visual Indicator of Color using dedicated arc generator */}
                <path
                   d={colorRingArc(slice) || undefined}
                   className={`
                    ${slice.data.colorGradientName.includes('red') ? 'fill-red-500' : ''}
                    ${slice.data.colorGradientName.includes('yellow') ? 'fill-yellow-400' : ''}
                    ${slice.data.colorGradientName.includes('cyan') ? 'fill-cyan-400' : ''}
                    ${slice.data.colorGradientName.includes('green') ? 'fill-green-500' : ''}
                    ${slice.data.colorGradientName.includes('blue') ? 'fill-blue-500' : ''}
                    ${slice.data.colorGradientName.includes('teal') ? 'fill-teal-500' : ''}
                    ${slice.data.colorGradientName.includes('violet') ? 'fill-violet-500' : ''}
                    ${slice.data.colorGradientName.includes('indigo') ? 'fill-indigo-500' : ''}
                    ${slice.data.colorGradientName.includes('pink') ? 'fill-pink-500' : ''}
                    ${slice.data.colorGradientName.includes('rose') ? 'fill-rose-400' : ''}
                    ${slice.data.colorGradientName.includes('crimson') ? 'fill-rose-700' : ''}
                    ${slice.data.colorGradientName.includes('dark_blue') ? 'fill-blue-900' : ''}
                   `}
                />

                <text
                  transform={`translate(${centroidX}, ${centroidY})`}
                  textAnchor="middle"
                  dy="0.35em"
                  className={`
                    text-xs font-bold pointer-events-none transition-colors duration-300
                    ${isActive ? 'fill-gray-900' : 'fill-gray-300'}
                  `}
                >
                  {slice.data.musicalKey.split(' ')[0]}
                </text>

                {/* Minor/Major Indicator Subtext */}
                <text
                   transform={`translate(${centroidX}, ${centroidY + 12})`}
                   textAnchor="middle"
                   className={`text-[8px] pointer-events-none uppercase ${isActive ? 'fill-gray-600' : 'fill-gray-500'}`}
                >
                   {slice.data.musicalKey.includes('Minor') ? 'min' : 'maj'}
                </text>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
};

export default CircleOfFifths;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, Wand2, AlertCircle, FileAudio, RotateCcw, ArrowUpCircle, Music, Gauge, Mic2, Sparkles, MoveRight, Loader2, CheckCircle2, FileText, Copy, Check } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string; // e.g. "To High Valence (Joy)"
  weights: string; // e.g. "V: +0.8, A: +0.6"
  advice: string;
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  // Use full emotion state to drive visualizations
  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);

  const activeSegmentIndexRef = useRef<number>(-1);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;

    if (wavesurfer.current) {
      wavesurfer.current.destroy();
    }

    wsRegions.current = RegionsPlugin.create();

    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(255, 255, 255, 0.1)',
      progressColor: 'rgba(56, 189, 248, 0.4)',
      cursorColor: '#ffffff',
      barWidth: 2,
      barGap: 3,
      height: 60,
      plugins: [wsRegions.current],
    });

    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => {
      setCurrentTime(t);
    });
    wavesurfer.current.on('finish', () => setIsPlaying(false));

    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });

    return () => {
      wavesurfer.current?.destroy();
    };
  }, [audioUrl]); 

  // Sync Logic: Update Emotion based on playback
  useEffect(() => {
    if (!segments.length) return;

    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });

    // Update if changed
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];

      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);

      // Update External Components
      if (onSegmentSelect) {
        onSegmentSelect(newEmotion);
      }
    }
  }, [currentTime, segments, onSegmentSelect]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("File is too large. Please upload an audio file under 150MB.");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);

      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      setCurrentEmotion(null);
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;

    const exportData = {
      trackInfo,
      segments,
      suggestions
    };

    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      console.error("Failed to copy", err);
    }
  };

  const togglePlay = () => {
    if (wavesurfer.current) wavesurfer.current.playPause();
  };

  const bufferToWav = (buffer: AudioBuffer): Blob => {
    const numOfChan = 1; 
    const length = buffer.length * numOfChan * 2 + 44;
    const bufferArr = new ArrayBuffer(length);
    const view = new DataView(bufferArr);
    const channels = [];
    let i, sample, offset = 0, pos = 0;
    for (i = 0; i < numOfChan; i++) channels.push(buffer.getChannelData(i));
    setUint32(0x46464952); setUint32(length - 8); setUint32(0x45564157); setUint32(0x20746d66); 
    setUint32(16); setUint16(1); setUint16(numOfChan); setUint32(buffer.sampleRate);
    setUint32(buffer.sampleRate * 2 * numOfChan); setUint16(numOfChan * 2); setUint16(16); 
    setUint32(0x61746164); setUint32(length - pos - 4); 
    while (pos < buffer.length) {
      for (i = 0; i < numOfChan; i++) {
        sample = Math.max(-1, Math.min(1, channels[i][pos])); 
        sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
        view.setInt16(44 + offset, sample, true);
        offset += 2;
      }
      pos++;
    }
    function setUint16(data: any) { view.setUint16(pos, data, true); pos += 2; }
    function setUint32(data: any) { view.setUint32(pos, data, true); pos += 4; }
    return new Blob([bufferArr], { type: 'audio/wav' });
  };

  const processAudioForAi = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
    if (file.size < 4 * 1024 * 1024) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: file.type }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
    }

    try {
      const arrayBuffer = await file.arrayBuffer();
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
      const targetSampleRate = 22050; 
      const offlineCtx = new OfflineAudioContext(1, audioBuffer.duration * targetSampleRate, targetSampleRate);
      const source = offlineCtx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(offlineCtx.destination);
      source.start();
      const resampledBuffer = await offlineCtx.startRendering();
      const wavBlob = bufferToWav(resampledBuffer);

      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
           const base64Data = (reader.result as string).split(',')[1];
           resolve({ inlineData: { data: base64Data, mimeType: 'audio/wav' }});
        };
        reader.onerror = reject;
        reader.readAsDataURL(wavBlob);
      });
    } catch (e) {
      throw new Error("Could not process audio file.");
    }
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);

    try {
      // Create fresh instance per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioPart = await processAudioForAi(audioFile);
      setAnalysisStep('analyzing_key');
      const trackPrompt = `
        Analyze this audio file (Mono/22kHz).
        Identify the Global Musical Key, Tempo (BPM), and main Chord Progression.
        Return strictly valid JSON:
        { "trackInfo": { "key": "string", "tempo": "string", "chords": "string" } }
      `;
      // Using gemini-3-flash-preview for general analysis tasks
      const trackResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: trackPrompt }] }
      });
      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) { console.warn("Failed to parse track info JSON", e); }
      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `
        Analyze this audio using the DEAM (Database for Emotional Analysis in Music) dataset principles.
        ${scriptContext ? `\nCONTEXT/SCRIPT PROVIDED BY USER: "${scriptContext}"\nUse this context to accurately align emotional shifts and audio events.` : ''}
        Tasks:
        1. Break the song into distinct emotional sections.
        2. Assign a Valence (V) and Arousal (A) score (-1.0 to 1.0) for each.
        3. Describe the physics of the sound in 'description'.
        4. Provide 3 remix suggestions.
        Return strictly valid JSON:
        {
          "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }],
          "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }]
        }
      `;
      // Using gemini-3-flash-preview for segment analysis
      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: segmentPrompt }] }
      });
      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);
      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);
      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);
        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.2)`, drag: false, resize: false,
        });
      });
    } catch (err: any) {
      console.error(err);
      setError("Analysis failed. " + (err.message || "Unknown error"));
    } finally {
      setAnalysisStep('idle');
    }
  };

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const isComplete = (step: AnalysisStep, target: AnalysisStep) => {
    const order = ['idle', 'optimizing', 'analyzing_key', 'analyzing_segments'];
    if (segments.length > 0 && step === 'idle') return true;
    if (step === 'idle') return false; 
    return order.indexOf(step) > order.indexOf(target);
  };

  const isActive = (step: AnalysisStep, target: AnalysisStep) => step === target;

  return (
    <div className="w-full p-4 md:p-8 max-w-7xl mx-auto text-gray-100">
       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          <div className="lg:col-span-4 space-y-6">
             <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
                   <FileAudio className="w-5 h-5 text-primary" />
                   Upload Source
                </h3>
                <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center hover:bg-gray-800/50 transition-colors cursor-pointer relative">
                   <input type="file" accept="audio/*" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                   <Upload className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                   <p className="text-sm text-gray-300">{audioFile ? audioFile.name : "Click to upload .wav or .mp3"}</p>
                </div>
                <div className="mt-4">
                  <label className="flex items-center gap-2 text-xs text-gray-400 font-semibold uppercase tracking-wider mb-2">
                    <FileText className="w-3 h-3" /> Script Context
                  </label>
                  <textarea
                    className="w-full bg-slate-900/50 border border-gray-600 rounded-lg p-3 text-sm text-gray-200 placeholder-gray-500 focus:outline-none focus:border-primary transition-colors resize-none h-24"
                    placeholder="Paste lyrics or scene cues..."
                    value={scriptContext}
                    onChange={(e) => setScriptContext(e.target.value)}
                  />
                </div>
                {error && <div className="mt-4 p-3 bg-red-900/20 border border-red-800 rounded-lg text-xs text-red-200">{error}</div>}
                <div className="mt-6 flex gap-2">
                   <button onClick={togglePlay} disabled={!audioFile} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-colors">
                      {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />} {isPlaying ? "Pause" : "Play"}
                   </button>
                   <button onClick={analyzeAudio} disabled={!audioFile || analysisStep !== 'idle'} className="flex-1 py-2 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-500 hover:to-purple-500 rounded-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all shadow-lg">
                      {analysisStep !== 'idle' ? <RotateCcw className="w-4 h-4 animate-spin" /> : <Wand2 className="w-4 h-4" />} Analyze
                   </button>
                </div>
             </div>
             {segments.length > 0 && (
               <div className="bg-surface rounded-2xl p-6 border border-gray-700">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Data Export</h3>
                    <button onClick={handleCopyData} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium ${copySuccess ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 'bg-gray-800 text-gray-300 hover:bg-gray-700'}`}>
                      {copySuccess ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />} Copy
                    </button>
                  </div>
                  <textarea readOnly value={JSON.stringify({ trackInfo, segments, suggestions }, null, 2)} className="w-full h-48 bg-slate-950/50 border border-gray-700 rounded-lg p-3 text-[10px] font-mono text-gray-500 resize-none" />
               </div>
             )}
          </div>

          <div className="lg:col-span-8 space-y-6">
             <audio ref={audioRef} src={audioUrl || undefined} crossOrigin="anonymous" className="hidden" />
             {/* Live Audio Visualizer */}
             <div className="bg-slate-900/80 border border-gray-700 rounded-2xl p-6 relative overflow-hidden h-[500px]">
                <LiveVisualizer 
                  mediaElement={audioRef.current} 
                  isPlaying={isPlaying} 
                  valence={currentEmotion?.valence ?? 0}
                  arousal={currentEmotion?.arousal ?? 0}
                />
                <div className="relative z-10 flex flex-col h-full justify-end pointer-events-none">
                  <div className="absolute top-0 right-0 text-sm font-mono text-primary font-bold bg-slate-900/50 px-2 py-1 rounded backdrop-blur">
                     {formatTime(currentTime)}
                  </div>
                  <div id="waveform" ref={containerRef} className="w-full pointer-events-auto opacity-40"></div>
                </div>
             </div>

             <div className="space-y-4">
                <div className="flex items-center justify-between">
                   <h3 className="text-xl font-bold text-white">Detected Segments</h3>
                   {analysisStep !== 'idle' && <div className="flex items-center gap-2 text-xs text-blue-400 bg-blue-900/20 px-3 py-1 rounded-full animate-pulse"><Loader2 className="w-3 h-3 animate-spin" /> Analyzing...</div>}
                </div>
                {segments.length > 0 ? (
                  <div className="grid gap-3">
                     {segments.map((seg, idx) => {
                       const start = parseTime(seg.startTime);
                       const end = parseTime(seg.endTime);
                       const isActive = currentTime >= start && currentTime < end && isPlaying;
                       const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
                       return (
                        <div key={idx} className={`border p-4 rounded-xl transition-all cursor-pointer relative overflow-hidden ${isActive ? 'bg-blue-900/20 border-blue-500' : 'bg-surface border-gray-700'}`} onClick={() => { if (wavesurfer.current) { wavesurfer.current.setTime(start); wavesurfer.current.play(); }}}>
                           <div className="absolute left-0 top-0 bottom-0 w-1" style={{ backgroundColor: colors.primaryColor }} />
                           <div className="flex justify-between items-center mb-1">
                              <span className="font-bold text-white capitalize">{seg.mood}</span>
                              <span className="text-[10px] font-mono text-gray-500">{seg.startTime} - {seg.endTime}</span>
                           </div>
                           <p className="text-xs text-gray-400">{seg.description}</p>
                        </div>
                       );
                     })}
                  </div>
                ) : (
                  analysisStep === 'idle' && <div className="text-center py-10 border border-dashed border-gray-700 rounded-xl text-gray-500">Upload audio to begin.</div>
                )}
             </div>
          </div>
       </div>
    </div>
  );
};

export default AppThree;

