        const analyser = ctx.createAnalyser();
        analyser.fftSize = 1024;
        analyser.smoothingTimeConstant = 0.8;
        analyserRef.current = analyser;
      }
      if (!sourceRef.current) {
        try {
          sourceRef.current = ctx.createMediaElementSource(mediaElement);
          sourceRef.current.connect(analyserRef.current!);
          analyserRef.current!.connect(ctx.destination);
        } catch (err) { console.warn(err); }
      }
    };
    initAudio();
  }, [mediaElement]);

  useEffect(() => {
    const ctx = audioContextRef.current;
    if (ctx && isPlaying && ctx.state === 'suspended') ctx.resume();
  }, [isPlaying]);

  useEffect(() => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const resize = () => {
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.offsetWidth * window.devicePixelRatio;
        canvas.height = parent.offsetHeight * window.devicePixelRatio;
        // Reset transform before scaling to prevent cumulative drift
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
      }
    };
    resize();
    window.addEventListener('resize', resize);

    const analyser = analyserRef.current;
    const bufferLength = analyser.frequencyBinCount;
    const freqData = new Uint8Array(bufferLength);
    const timeData = new Uint8Array(bufferLength);

    const render = () => {
      analyser.getByteFrequencyData(freqData);
      analyser.getByteTimeDomainData(timeData);

      const w = canvas.width / window.devicePixelRatio;
      const h = canvas.height / window.devicePixelRatio;
      const cx = w / 2;
      const cy = h / 2;
      const time = Date.now() / 1000;

      // Calculate Bass Energy for Pulse
      let bass = 0;
      for (let i = 0; i < 10; i++) bass += freqData[i];
      bass = bass / 10 / 255; // 0..1

      // Physics: Valence to Angle, Arousal to Radius for Background Nodes
      const arousalMod = (arousal + 1) / 2; // Map -1..1 to 0..1
      const targetAngle = Math.PI * (valence + 1) - Math.PI / 2;
      const targetRadius = Math.min(w, h) * 0.22 * (1.1 + arousal);

      // Clear with absolute black
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, w, h);

      // --- LAYER 1: 12 Emotional Nodes (The Circle) ---
      const orbitRadius = Math.min(w, h) * 0.35;
      EMOTIONAL_KEYS.forEach((node) => {
        const theta = -Math.PI / 2 + (node.keyPosition - 1) * (Math.PI / 6);
        const nx = cx + Math.cos(theta) * orbitRadius;
        const ny = cy + Math.sin(theta) * orbitRadius;

        let angDiff = Math.abs(targetAngle - theta);
        while (angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI * 2);
        const isActive = angDiff < 0.5;
        const proximity = Math.max(0, 1 - angDiff);

        ctx.beginPath();
        const size = 4 + proximity * 12 + bass * 10;
        ctx.arc(nx, ny, size, 0, Math.PI * 2);

        ctx.shadowBlur = isActive ? 20 + bass * 30 : 0;
        ctx.shadowColor = node.primaryColor;
        ctx.fillStyle = node.primaryColor;
        ctx.globalAlpha = 0.2 + proximity * 0.8;
        ctx.fill();
        ctx.shadowBlur = 0;

        // --- LAYER 2: Harmonic Pentagrams (Fifths) ---
        if (isActive) {
          ctx.beginPath();
          ctx.strokeStyle = node.primaryColor;
          ctx.lineWidth = 1 + proximity * 2;
          ctx.globalAlpha = proximity * 0.3;

          const prevIdx = (node.keyPosition - 2 + 12) % 12;
          const pNode = EMOTIONAL_KEYS[prevIdx];
          const pt = -Math.PI / 2 + (pNode.keyPosition - 1) * (Math.PI / 6);
          ctx.moveTo(nx, ny);
          ctx.lineTo(cx + Math.cos(pt) * orbitRadius, cy + Math.sin(pt) * orbitRadius);

          const nextIdx = (node.keyPosition) % 12;
          const nNode = EMOTIONAL_KEYS[nextIdx];
          const nt = -Math.PI / 2 + (nNode.keyPosition - 1) * (Math.PI / 6);
          ctx.lineTo(cx + Math.cos(nt) * orbitRadius, cy + Math.sin(nt) * orbitRadius);
          ctx.stroke();
        }
      });

      // --- LAYER 3: Emotional Particle & Harmonic Vector ---
      const px = cx + Math.cos(targetAngle) * targetRadius;
      const py = cy + Math.sin(targetAngle) * targetRadius;

      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(px, py);
      ctx.strokeStyle = `hsla(${time * 50 % 360}, 100%, 70%, 0.4)`;
      ctx.setLineDash([5, 5]);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.beginPath();
      ctx.arc(px, py, 10 + bass * 15, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 30;
      ctx.shadowColor = `hsl(${time * 50 % 360}, 100%, 50%)`;
      ctx.globalAlpha = 1;
      ctx.fill();
      ctx.shadowBlur = 0;

      // --- LAYER 4: Central Multi-Layered Oscilloscope (Classic Horizontal) ---
      const scopeWidth = Math.min(w * 0.65, 520);
      const xStart = cx - scopeWidth / 2;
      const xEnd = cx + scopeWidth / 2;
      const ampBase = 40 + bass * 60 + arousalMod * 40;

      // Create Animated Gradient for the scope lines
      const gradient = ctx.createLinearGradient(xStart, 0, xEnd, 0);
      const hueBase = (time * 60) % 360;
      gradient.addColorStop(0, `hsla(${hueBase}, 100%, 70%, 0)`);
      gradient.addColorStop(0.2, `hsla(${(hueBase + 40) % 360}, 100%, 70%, 0.8)`);
      gradient.addColorStop(0.5, `hsla(${(hueBase + 80) % 360}, 100%, 80%, 1)`);
      gradient.addColorStop(0.8, `hsla(${(hueBase + 120) % 360}, 100%, 70%, 0.8)`);
      gradient.addColorStop(1, `hsla(${(hueBase + 160) % 360}, 100%, 70%, 0)`);

      const drawScopeLayer = (gain: number, alpha: number, sampleOffset: number) => {
        ctx.beginPath();
        ctx.globalAlpha = alpha * (0.6 + bass * 0.4);
        ctx.strokeStyle = gradient;
        ctx.lineWidth = 2.5;

        for (let i = 0; i < bufferLength; i++) {
          const t = i / (bufferLength - 1);
          // Loop around sample offset for phase shifting effect
          const sampleIndex = (i + sampleOffset) % bufferLength;
          const s = (timeData[sampleIndex] - 128) / 128;

          const x = xStart + t * scopeWidth;
          const y = cy + s * ampBase * gain;

          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      };

      // Draw 3 passes with different gains and phase offsets
      drawScopeLayer(0.35, 0.55, 0);
      drawScopeLayer(0.65, 0.30, 4);
      drawScopeLayer(0.95, 0.15, 12);

      animationRef.current = requestAnimationFrame(render);
    };

    render();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [isPlaying, valence, arousal]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full rounded-2xl pointer-events-none" />;
};

