import { GoogleGenAI } from "@google/genai";
import { EmotionalKeyData } from "../types";

export const generateEmotionalInsight = async (data: EmotionalKeyData): Promise<string> => {
  // Instantiate right before call to ensure up-to-date API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Analyze the musical key of ${data.musicalKey} and its association with the emotion "${data.emotion}".
    The mood is described as "${data.mood}".
    Valence: ${data.valence}, Arousal: ${data.arousal}.

    1. Briefly explain why this key might evoke this specific emotion musically (e.g., resonance, historical usage, brightness/darkness).
    2. Describe a vivid short scene or visual setting that embodies this combination.
    3. Suggest a simple chord progression or musical texture that a composer could use to express this.

    Keep the response concise (under 200 words) but poetic and insightful. Format with clear paragraphs.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "No insight generated.";
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    // Return specific error message for component handling
    if (error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED')) {
      throw new Error('QUOTA_EXCEEDED');
    }
    return "Unable to generate insight at this moment.";
  }
};

