import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, Wand2, AlertCircle, FileAudio, RotateCcw, ArrowUpCircle, Music, Gauge, Mic2, Sparkles, MoveRight, Loader2, CheckCircle2, FileText, Copy, Check, Terminal, Key } from 'lucide-react';
