      // Draw Glass Panel Background
      ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
      ctx.fillRect(0, bandTop, w, RHYTHM_H);
      ctx.beginPath();
      ctx.moveTo(0, bandTop);
      ctx.lineTo(w, bandTop);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
      ctx.lineWidth = 1;
      ctx.stroke();

      // Draw Plumes (Vertical Columns)
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';

      // Dynamic scaling for plume animation based on arousal (-1 to 1)
      const arousalFactor = 1 + arousal * 0.5; // Speed multiplier: 0.5 to 1.5
      const waveComplexity = 1 + arousal * 0.2; // Frequency multiplier: 0.8 to 1.2

      const drawPlumesPass = (alphaMult: number, isBlur: boolean) => {
        for (let x = 0; x < w; x += 4) {
          // Compute heights with sine movement and arousal-based dynamics
          const hLow = low * RHYTHM_H * (0.8 + 0.2 * Math.sin(time * arousalFactor + x * 0.02 * waveComplexity + arousal));
          const hMid = mid * RHYTHM_H * (0.6 + 0.3 * Math.sin(time * 1.3 * arousalFactor + x * 0.035 * waveComplexity - arousal));
          const hHigh = high * RHYTHM_H * (0.4 + 0.4 * Math.sin(time * 2.2 * arousalFactor + x * 0.05 * waveComplexity + arousal * 2));

          const colW = isBlur ? 6 : 3;
          const xOff = isBlur ? -1 : 0;

          // LOW Band (Magenta/Violet Plume)
          if (hLow > 1) {
            const lowGrad = ctx.createLinearGradient(0, bandBottom, 0, bandBottom - hLow);
            lowGrad.addColorStop(0, `rgba(208, 0, 255, ${0.35 * alphaMult})`);
            lowGrad.addColorStop(1, 'rgba(208, 0, 255, 0)');
            ctx.fillStyle = lowGrad;
            ctx.fillRect(x + xOff, bandBottom - hLow, colW, hLow);
          }

          // MID Band (Hacker Green/Cyan Spike)
          if (hMid > 1) {
            const midGrad = ctx.createLinearGradient(0, bandBottom, 0, bandBottom - hMid);
            midGrad.addColorStop(0, `rgba(0, 255, 65, ${0.25 * alphaMult})`);
            midGrad.addColorStop(1, 'rgba(0, 255, 65, 0)');
            ctx.fillStyle = midGrad;
            ctx.fillRect(x + xOff + 1, bandBottom - hMid, colW - 1, hMid);
          }

          // HIGH Band (White Flicker Shimmer)
          if (hHigh > 2 && Math.random() > 0.4) {
             const highGrad = ctx.createLinearGradient(0, bandBottom, 0, bandBottom - hHigh);
             highGrad.addColorStop(0, `rgba(255, 255, 255, ${0.15 * alphaMult * high})`);
             highGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
             ctx.fillStyle = highGrad;
             ctx.fillRect(x + xOff + 2, bandBottom - hHigh, 1, hHigh);
          }
        }
      };

      // Pass 1: Blurred Bloom
      drawPlumesPass(0.5, true);
      // Pass 2: Sharp core
      drawPlumesPass(1.0, false);

      ctx.restore();

      // --- 3. Layer: 12 Emotional Nodes ---
      const orbitRadius = Math.min(w, visibleHeight) * 0.38;
      const targetAngle = Math.PI * (valence + 1) - Math.PI / 2;
      const targetRadius = Math.min(w, visibleHeight) * 0.25 * (1.1 + arousal);

      EMOTIONAL_KEYS.forEach((node) => {
        const theta = -Math.PI / 2 + (node.keyPosition - 1) * (Math.PI / 6);
        const nx = cx + Math.cos(theta) * orbitRadius;
        const ny = cy + Math.sin(theta) * orbitRadius;

        let angDiff = Math.abs(targetAngle - theta);
        while (angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI * 2);
        const isActive = angDiff < 0.5;
        const proximity = Math.max(0, 1 - angDiff);

        ctx.beginPath();
        const size = 4 + proximity * 12 + low * 15;
        ctx.arc(nx, ny, size, 0, Math.PI * 2);

        ctx.shadowBlur = isActive ? 20 + low * 40 : 0;
        ctx.shadowColor = node.primaryColor;
        ctx.fillStyle = node.primaryColor;
        ctx.globalAlpha = 0.2 + proximity * 0.8;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Add Note Letter to the Circle
        const noteLetter = node.musicalKey.split(' ')[0];
        const isMinor = node.musicalKey.includes('Minor');
        const displayLetter = isMinor ? noteLetter.toLowerCase() : noteLetter;

        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        // Dynamic font size based on proximity and size
        const fontSize = Math.max(6, Math.min(size * 0.8, 11));
        ctx.font = `bold ${fontSize}px "Fira Code", monospace`;
        ctx.fillStyle = isActive ? '#000' : 'rgba(255, 255, 255, 0.85)';
        ctx.globalAlpha = 0.4 + proximity * 0.6;
        ctx.fillText(displayLetter, nx, ny);
        ctx.restore();

        if (isActive) {
          ctx.beginPath();
          ctx.strokeStyle = node.primaryColor;
          ctx.lineWidth = 1 + proximity * 2;
          ctx.globalAlpha = proximity * 0.3;
          const prevIdx = (node.keyPosition - 2 + 12) % 12;
          const pNode = EMOTIONAL_KEYS[prevIdx];
          const pt = -Math.PI / 2 + (pNode.keyPosition - 1) * (Math.PI / 6);
          ctx.moveTo(nx, ny);
          ctx.lineTo(cx + Math.cos(pt) * orbitRadius, cy + Math.sin(pt) * orbitRadius);
          const nextIdx = (node.keyPosition) % 12;
          const nNode = EMOTIONAL_KEYS[nextIdx];
          const nt = -Math.PI / 2 + (nNode.keyPosition - 1) * (Math.PI / 6);
          ctx.lineTo(cx + Math.cos(nt) * orbitRadius, cy + Math.sin(nt) * orbitRadius);
          ctx.stroke();
        }
      });

      // --- 4. Layer: Emotional Particle & Harmonic Vector ---
      const px = cx + Math.cos(targetAngle) * targetRadius;
      const py = cy + Math.sin(targetAngle) * targetRadius;

      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(px, py);
      ctx.strokeStyle = `hsla(${time * 50 % 360}, 100%, 70%, 0.4)`;
      ctx.setLineDash([5, 5]);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.beginPath();
      ctx.arc(px, py, 10 + low * 20, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 30;
      ctx.shadowColor = `hsl(${time * 50 % 360}, 100%, 50%)`;
      ctx.globalAlpha = 1;
      ctx.fill();
      ctx.shadowBlur = 0;

      // --- 5. Layer: Central Multi-Layered Oscilloscope ---
      const scopeWidth = Math.min(w * 0.65, 520);
      const xStart = cx - scopeWidth / 2;
      const xEnd = cx + scopeWidth / 2;
      const arousalMod = (arousal + 1) / 2;
      const ampBase = 40 + low * 80 + arousalMod * 40;

      const scopeGrad = ctx.createLinearGradient(xStart, 0, xEnd, 0);
      const hueBase = (time * 60) % 360;
      scopeGrad.addColorStop(0, `hsla(${hueBase}, 100%, 70%, 0)`);
      scopeGrad.addColorStop(0.2, `hsla(${(hueBase + 40) % 360}, 100%, 70%, 0.8)`);
      scopeGrad.addColorStop(0.5, `hsla(${(hueBase + 80) % 360}, 100%, 80%, 1)`);
      scopeGrad.addColorStop(0.8, `hsla(${(hueBase + 120) % 360}, 100%, 70%, 0.8)`);
      scopeGrad.addColorStop(1, `hsla(${(hueBase + 160) % 360}, 100%, 70%, 0)`);

      const drawScopeLayer = (gain: number, alpha: number, sampleOffset: number) => {
        ctx.beginPath();
        ctx.globalAlpha = alpha * (0.6 + low * 0.4);
        ctx.strokeStyle = scopeGrad;
        ctx.lineWidth = 2.5;

        for (let i = 0; i < bufferLength; i++) {
          const t = i / (bufferLength - 1);
          const sampleIndex = (i + sampleOffset) % bufferLength;
          const s = (timeData[sampleIndex] - 128) / 128;
          const x = xStart + t * scopeWidth;
          const y = cy + s * ampBase * gain;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      };

      drawScopeLayer(0.35, 0.55, 0);
      drawScopeLayer(0.65, 0.30, 4);
      drawScopeLayer(0.95, 0.15, 12);

      animationRef.current = requestAnimationFrame(render);
    };

    render();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [isPlaying, valence, arousal, reservedFooterHeight]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full rounded-2xl pointer-events-none" />;
};

export default LiveVisualizer;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, AlertCircle, Loader2, FileText, Terminal, Key, Activity } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string;
  weights: string;
  advice: string;
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);
  const activeSegmentIndexRef = useRef<number>(-1);

  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;
    if (wavesurfer.current) wavesurfer.current.destroy();
    wsRegions.current = RegionsPlugin.create();
    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(208, 0, 255, 0.25)',
      progressColor: 'rgba(0, 255, 65, 0.6)',
      cursorColor: '#00ff41',
      barWidth: 3,
      barGap: 3,
      height: 120, // Increased height for better readability
      plugins: [wsRegions.current],
    });
    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => setCurrentTime(t));
    wavesurfer.current.on('finish', () => setIsPlaying(false));
    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });
    return () => wavesurfer.current?.destroy();
  }, [audioUrl]); 

  useEffect(() => {
    if (!segments.length) return;
    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];
      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);
      if (onSegmentSelect) onSegmentSelect(newEmotion);
    }
  }, [currentTime, segments, onSegmentSelect]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("FILE_TOO_LARGE: MAX 150MB");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);
      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      setCurrentEmotion(null);
    }
  };

  const handleOpenKeyDialog = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;
    const exportData = { trackInfo, segments, suggestions };
    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) { console.error("COPY_FAIL", err); }
  };

  const togglePlay = () => wavesurfer.current && wavesurfer.current.playPause();

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Inline processing to keep it minimal
      const reader = new FileReader();
      const audioPart = await new Promise<any>((resolve, reject) => {
        reader.onloadend = () => resolve({ inlineData: { data: (reader.result as string).split(',')[1], mimeType: audioFile.type }});
        reader.onerror = reject;
        reader.readAsDataURL(audioFile);
      });

      setAnalysisStep('analyzing_key');
      const trackPrompt = `GLOBAL_TRACK_ANALYSIS: Musical Key, Tempo (BPM), Chord Progression. Return JSON: { "trackInfo": { "key": "str", "tempo": "str", "chords": "str" } }`;
      const trackResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: trackPrompt }] }
      });
      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) { console.warn("PARSE_ERROR_TRACK", e); }

      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `EMO_SEGMENTATION_ANALYSIS: Break into emotional sections. Valence/Arousal (-1.0 to 1.0). ${scriptContext ? `CONTEXT: "${scriptContext}"` : ''} Return JSON: { "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }], "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }] }`;
      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: segmentPrompt }] }
      });
      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);
      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);

      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);
        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.15)`, drag: false, resize: false,
        });
      });
    } catch (err: any) {
      if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
        setError("QUOTA_EXCEEDED");
      } else {
        setError("ANALYSIS_HALTED: " + (err.message || "SIGNAL_LOST"));
      }
    } finally { setAnalysisStep('idle'); }
  };

  return (
    <div className="w-full p-4 md:p-8 max-w-7xl mx-auto text-hackerGreen">
       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-4 space-y-6">
             <div className="terminal-box glass-shine p-6">
                <h3 className="text-sm font-bold mb-6 flex items-center gap-2 uppercase tracking-widest">
                   <Terminal className="w-4 h-4 text-neonViolet" /> INPUT_SOURCE
                </h3>
                <div className="border border-dashed border-neonViolet/50 bg-black/50 rounded-lg p-6 text-center hover:bg-neonViolet/5 transition-all cursor-pointer relative group">
                   <input type="file" accept="audio/*" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                   <Upload className="w-8 h-8 mx-auto text-neonViolet mb-2 group-hover:scale-110 transition-transform" />
                   <p className="text-[10px] hacker-text uppercase tracking-widest">{audioFile ? audioFile.name : "LOAD_WAV_OR_MP3"}</p>
                </div>
                <div className="mt-6">
                  <label className="flex items-center gap-2 text-[9px] hacker-text-dim font-bold uppercase tracking-[0.2em] mb-2">
                    <FileText className="w-3 h-3" /> SCRIPT_METADATA_INJECTOR
                  </label>
                  <textarea
                    className="w-full bg-black/40 border border-neonViolet/30 rounded-lg p-3 text-xs hacker-text placeholder-neonViolet/30 focus:outline-none focus:border-neonViolet transition-colors resize-none h-24"
                    placeholder="ENTER SCENE CONTEXT OR LYRICS..."
                    value={scriptContext}
                    onChange={(e) => setScriptContext(e.target.value)}
                  />
                </div>

                {error === "QUOTA_EXCEEDED" ? (
                  <div className="mt-4 p-4 border border-red-500 bg-red-900/20 rounded flex flex-col gap-3">
                     <div className="flex items-center gap-2">
                       <AlertCircle className="text-red-500 w-4 h-4" />
                       <h4 className="text-red-500 font-bold text-[10px] uppercase">QUOTA_EXCEEDED</h4>
                     </div>
                     <p className="text-[9px] hacker-text-dim">Analysis requires higher throughput. Switch to a paid key.</p>
                     <button 
                       onClick={handleOpenKeyDialog}
                       className="w-full py-2 bg-red-950 border border-red-500 text-red-500 text-[10px] font-bold uppercase tracking-widest animate-pulse"
                     >
                       UPGRADE_KEY
                     </button>
                  </div>
                ) : error && (
                  <div className="mt-4 p-3 bg-red-950/30 border border-red-900 text-[10px] text-red-500 font-bold uppercase">{error}</div>
                )}

                <div className="mt-6 flex gap-2">
                   <button onClick={togglePlay} disabled={!audioFile} className="flex-1 py-2 bg-black border border-neonViolet text-neonViolet text-[10px] font-bold uppercase tracking-widest hover:bg-neonViolet hover:text-black transition-all disabled:opacity-30">
                      {isPlaying ? <Pause className="w-3 h-3 mx-auto" /> : <Play className="w-3 h-3 mx-auto" />}
                   </button>
                   <button onClick={analyzeAudio} disabled={!audioFile || analysisStep !== 'idle'} className="flex-1 py-2 bg-black border border-hackerGreen text-hackerGreen text-[10px] font-bold uppercase tracking-widest hover:bg-hackerGreen hover:text-black transition-all shadow-[0_0_10px_rgba(0,255,65,0.3)] disabled:opacity-30">
                      {analysisStep !== 'idle' ? 'RUNNING...' : 'PROCESS_SIGNAL'}
                   </button>
                </div>
             </div>
             {segments.length > 0 && (
               <div className="terminal-box p-6">
                  <div className="flex items-center justify-between mb-4 pb-2 border-b border-neonViolet/30">
                    <h3 className="text-[10px] font-bold hacker-text-dim uppercase tracking-[0.3em]">TELEMETRY_EXPORT</h3>
                    <button onClick={handleCopyData} className={`flex items-center gap-2 px-3 py-1 text-[9px] font-bold uppercase tracking-widest transition-all ${copySuccess ? 'text-hackerGreen' : 'text-neonViolet hover:bg-neonViolet/10'}`}>
                      {copySuccess ? 'COPIED' : 'COPY_BUFFER'}
                    </button>
                  </div>
                  <textarea readOnly value={JSON.stringify({ trackInfo, segments, suggestions }, null, 2)} className="w-full h-40 bg-black text-[9px] hacker-text-dim border-none resize-none focus:outline-none scrollbar-hide" />
               </div>
             )}
          </div>

          <div className="lg:col-span-8 space-y-6">
             <audio ref={audioRef} src={audioUrl || undefined} crossOrigin="anonymous" className="hidden" />

             {/* Visualizer Card (Nodes + Oscillator only) */}
             <div className="terminal-box relative overflow-hidden h-[500px] group shadow-[0_0_20px_rgba(208,0,255,0.15)] flex flex-col">
                <div className="absolute inset-0 z-0">
                  <LiveVisualizer 
                    mediaElement={audioRef.current} 
                    isPlaying={isPlaying} 
                    valence={currentEmotion?.valence ?? 0}
                    arousal={currentEmotion?.arousal ?? 0}
                    reservedFooterHeight={0}
                  />
                </div>

                <div className="relative z-10 p-4 pointer-events-none">
                  <div className="text-[10px] font-bold hacker-text bg-black/60 backdrop-blur border border-neonViolet/40 inline-block px-3 py-1 rounded shadow-[0_0_10px_rgba(208,0,255,0.2)]">
                     SYS_TIME: {formatTime(currentTime)}
                  </div>
                </div>
             </div>

             {/* Rhythm / Timeline Panel (Separated out) */}
             <div className="terminal-box glass-shine p-6 space-y-4">
                <div className="flex items-center justify-between border-b border-neonViolet/20 pb-2">
                   <h3 className="text-[10px] font-bold hacker-text-dim uppercase tracking-[0.3em] flex items-center gap-2">
                      <Activity className="w-3 h-3 text-neonViolet" /> RHYTHM_TIMELINE_MATRIX
                   </h3>
                   <div className="text-[9px] hacker-text-dim italic">-- SIGNAL_FEED_CONNECTED --</div>
                </div>
                <div id="waveform" ref={containerRef} className="w-full h-[120px] filter hue-rotate-[280deg]"></div>
             </div>

             <div className="space-y-4">
                <div className="flex items-center justify-between">
                   <h3 className="text-xl font-bold hacker-text tracking-tighter uppercase tracking-[0.1em]">DETECTED_EMO_SEGMENTS</h3>
                   {analysisStep !== 'idle' && <div className="flex items-center gap-2 text-[10px] text-hackerGreen bg-hackerGreen/10 border border-hackerGreen/30 px-3 py-1 animate-pulse uppercase tracking-widest"><Loader2 className="w-3 h-3 animate-spin" /> SCANNING_MATRIX...</div>}
                </div>
                {segments.length > 0 ? (
                  <div className="grid gap-3">
                     {segments.map((seg, idx) => {
                       const start = parseTime(seg.startTime);
                       const end = parseTime(seg.endTime);
                       const isActive = currentTime >= start && currentTime < end && isPlaying;
                       const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
                       return (
                        <div key={idx} className={`terminal-box glass-shine p-4 transition-all cursor-pointer relative overflow-hidden group ${isActive ? 'shadow-[0_0_20px_rgba(0,255,65,0.3)] border-hackerGreen' : 'border-neonViolet/30 hover:border-neonViolet'}`} onClick={() => { if (wavesurfer.current) { wavesurfer.current.setTime(start); wavesurfer.current.play(); }}}>
                           <div className="absolute left-0 top-0 bottom-0 w-1" style={{ backgroundColor: colors.primaryColor }} />
                           <div className="flex justify-between items-center mb-1">
                              <span className="font-bold hacker-text uppercase text-xs tracking-widest">{seg.mood}</span>
                              <span className="text-[9px] hacker-text-dim uppercase tracking-widest">{seg.startTime} >> {seg.endTime}</span>
                           </div>
                           <p className="text-[10px] hacker-text-dim group-hover:text-hackerGreen transition-colors italic">"{seg.description}"</p>
                        </div>
                       );
                     })}
                  </div>
                ) : (
                  analysisStep === 'idle' && <div className="text-center py-10 terminal-box border-dashed border-neonViolet/20 hacker-text-dim text-[10px] uppercase tracking-widest">SIGNAL_INPUT_REQUIRED</div>
                )}
             </div>
          </div>
       </div>
    </div>
  );
};

export default AppThree;

import React, { useEffect, useRef } from 'react';
import { EMOTIONAL_KEYS } from '../constants';

interface LiveVisualizerProps {
  mediaElement: HTMLMediaElement | null;
  isPlaying: boolean;
  valence: number;
  arousal: number;
  reservedFooterHeight?: number; 
}

const RHYTHM_H = 90;
const FOOTER_PAD = 14;

const LiveVisualizer: React.FC<LiveVisualizerProps> = ({ 
  mediaElement, 
  isPlaying, 
  valence, 
  arousal,
  reservedFooterHeight = 90 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // Persistence for smoothed audio envelopes
  const envelopes = useRef({
    low: 0,
    mid: 0,
    high: 0,
    overall: 0
  });

  // Audio setup
  useEffect(() => {
    if (!mediaElement) return;
    const initAudio = () => {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      if (!analyserRef.current) {
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 1024;
        analyser.smoothingTimeConstant = 0.8;
        analyserRef.current = analyser;
      }
      if (!sourceRef.current) {
        try {
          sourceRef.current = ctx.createMediaElementSource(mediaElement);
          sourceRef.current.connect(analyserRef.current!);
          analyserRef.current!.connect(ctx.destination);
        } catch (err) { console.warn(err); }
      }
    };
    initAudio();
  }, [mediaElement]);

  useEffect(() => {
    const ctx = audioContextRef.current;
    if (ctx && isPlaying && ctx.state === 'suspended') ctx.resume();
  }, [isPlaying]);

  useEffect(() => {
    if (!canvasRef.current || !analyserRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const resize = () => {
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.offsetWidth * window.devicePixelRatio;
        canvas.height = parent.offsetHeight * window.devicePixelRatio;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
      }
    };
    resize();
    window.addEventListener('resize', resize);

    const analyser = analyserRef.current;
    const bufferLength = analyser.frequencyBinCount;
    const freqData = new Uint8Array(bufferLength);
    const timeData = new Uint8Array(bufferLength);

    const render = () => {
      analyser.getByteFrequencyData(freqData);
      analyser.getByteTimeDomainData(timeData);

      const w = canvas.width / window.devicePixelRatio;
      const h = canvas.height / window.devicePixelRatio;

      // Since rhythm timeline panel is moved out, we use the full visible area
      const useFullHeight = reservedFooterHeight === 0;
      const effectiveStripH = useFullHeight ? 0 : RHYTHM_H;
      const effectiveFooterPad = useFullHeight ? 0 : FOOTER_PAD;

      const visibleHeight = h - (effectiveStripH + effectiveFooterPad);
      const cx = w / 2;
      const cy = h / 2;
      const time = Date.now() / 1000;

      // --- 1. Audio Frequency Analysis ---
      let lowSum = 0, midSum = 0, highSum = 0, totalSum = 0;
      // Low (Bass): bins 0-3 (up to ~170Hz)
      for (let i = 0; i < 4; i++) {
        lowSum += freqData[i];
        totalSum += freqData[i];
      }
      // Mid (Voice/Melody): bins 5-70 (~200Hz to 3kHz)
      for (let i = 4; i < 70; i++) {
        midSum += freqData[i];
        totalSum += freqData[i];
      }
      // High (Hats/Air): bins 71-232 (3kHz to 10kHz)
      for (let i = 71; i < 232; i++) {
        highSum += freqData[i];
        totalSum += freqData[i];
      }

      const lowTarget = lowSum / 4 / 255;
      const midTarget = midSum / 66 / 255;
      const highTarget = highSum / 161 / 255;
      const overallTarget = totalSum / 232 / 255;

      // Envelope Smoothers
      envelopes.current.low += (lowTarget - envelopes.current.low) * 0.15;
      envelopes.current.mid += (midTarget - envelopes.current.mid) * 0.15;
      envelopes.current.high += (highTarget - envelopes.current.high) * 0.15;
      envelopes.current.overall += (overallTarget - envelopes.current.overall) * 0.1;

      const { low, mid, high, overall } = envelopes.current;

      // Clear
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, w, h);

      // --- 2. Color/Intensity Computation (Reactive) ---
      // mid (voice) pushes toward green/cyan, highs push blue/purple, bass pushes magenta/red
      const midFactor = mid / (mid + high + 0.001);
      const highFactor = high / (mid + high + 0.001);

      // Hue Mapping: Voice (mid) around 150 (Green/Cyan), Highs around 240 (Blue), Bass blends into 300 (Magenta)
      let reactiveHue = 150 * midFactor + 240 * highFactor;
      if (low > 0.4) reactiveHue = (reactiveHue * 0.7 + 300 * 0.3) % 360;

      const reactiveAlpha = 0.25 + overall * 0.55;
      const reactiveLightness = 35 + overall * 35;
      const reactiveLineWidth = 1.5 + overall * 2.5;

      // --- 3. Rhythm Plume Strip (Background Effect) ---
      if (!useFullHeight) {
        const bandTop = h - RHYTHM_H - FOOTER_PAD;
        const bandBottom = h - FOOTER_PAD;

        ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
        ctx.fillRect(0, bandTop, w, RHYTHM_H);
        ctx.beginPath();
        ctx.moveTo(0, bandTop); ctx.lineTo(w, bandTop);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        const arousalFactor = 1 + arousal * 0.5;
        const waveComplexity = 1 + arousal * 0.2;

        const drawPlumesPass = (alphaMult: number, isBlur: boolean) => {
          for (let x = 0; x < w; x += 4) {
            const hLow = low * RHYTHM_H * (0.8 + 0.2 * Math.sin(time * arousalFactor + x * 0.02 * waveComplexity + arousal));
            const hMid = mid * RHYTHM_H * (0.6 + 0.3 * Math.sin(time * 1.3 * arousalFactor + x * 0.035 * waveComplexity - arousal));
            const hHigh = high * RHYTHM_H * (0.4 + 0.4 * Math.sin(time * 2.2 * arousalFactor + x * 0.05 * waveComplexity + arousal * 2));
            const colW = isBlur ? 6 : 3;
            if (hLow > 1) {
              ctx.fillStyle = `rgba(208, 0, 255, ${0.35 * alphaMult})`;
              ctx.fillRect(x, bandBottom - hLow, colW, hLow);
            }
            if (hMid > 1) {
              ctx.fillStyle = `rgba(0, 255, 65, ${0.25 * alphaMult})`;
              ctx.fillRect(x + 1, bandBottom - hMid, colW - 1, hMid);
            }
          }
        };
        drawPlumesPass(0.5, true);
        drawPlumesPass(1.0, false);
        ctx.restore();
      }

      // --- 4. Emotional Nodes ---
      const orbitRadius = Math.min(w, h) * 0.38;
      const targetAngle = Math.PI * (valence + 1) - Math.PI / 2;
      const targetRadius = Math.min(w, h) * 0.25 * (1.1 + arousal);

      EMOTIONAL_KEYS.forEach((node) => {
        const theta = -Math.PI / 2 + (node.keyPosition - 1) * (Math.PI / 6);
        const nx = cx + Math.cos(theta) * orbitRadius;
        const ny = cy + Math.sin(theta) * orbitRadius;
        let angDiff = Math.abs(targetAngle - theta);
        while (angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI * 2);
        const isActive = angDiff < 0.5;
        const proximity = Math.max(0, 1 - angDiff);

        ctx.beginPath();
        const size = 4 + proximity * 12 + low * 15;
        ctx.arc(nx, ny, size, 0, Math.PI * 2);
        ctx.shadowBlur = isActive ? 20 + low * 40 : 0;
        ctx.shadowColor = node.primaryColor;
        ctx.fillStyle = node.primaryColor;
        ctx.globalAlpha = 0.2 + proximity * 0.8;
        ctx.fill();
        ctx.shadowBlur = 0;

        const displayLetter = node.musicalKey.includes('Minor') ? node.musicalKey[0].toLowerCase() : node.musicalKey[0];
        ctx.save();
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.font = `bold ${Math.max(6, Math.min(size * 0.8, 11))}px monospace`;
        ctx.fillStyle = isActive ? '#000' : 'rgba(255,255,255,0.8)';
        ctx.fillText(displayLetter, nx, ny);
        ctx.restore();
      });

      // --- 5. Emotional Particle & Vector (REACTIVE) ---
      const px = cx + Math.cos(targetAngle) * targetRadius;
      const py = cy + Math.sin(targetAngle) * targetRadius;

      ctx.beginPath();
      ctx.moveTo(cx, cy); ctx.lineTo(px, py);
      ctx.strokeStyle = `hsla(${reactiveHue}, 100%, ${reactiveLightness}%, ${reactiveAlpha * 0.5})`;
      ctx.setLineDash([5, 5]);
      ctx.stroke(); ctx.setLineDash([]);

      ctx.beginPath();
      ctx.arc(px, py, 10 + low * 20, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 30 + low * 30; // Extra bloom on bass
      ctx.shadowColor = `hsla(${reactiveHue}, 100%, 50%, 0.8)`;
      ctx.globalAlpha = 1;
      ctx.fill(); ctx.shadowBlur = 0;

      // --- 6. Central Oscilloscope (REACTIVE) ---
      const scopeWidth = Math.min(w * 0.65, 520);
      const xStart = cx - scopeWidth / 2;
      const xEnd = cx + scopeWidth / 2;
      const ampBase = 40 + low * 100 + arousal * 30;

      const scopeGrad = ctx.createLinearGradient(xStart, 0, xEnd, 0);
      scopeGrad.addColorStop(0, `hsla(${reactiveHue}, 100%, ${reactiveLightness}%, 0)`);
      scopeGrad.addColorStop(0.5, `hsla(${reactiveHue}, 100%, ${reactiveLightness + 10}%, ${reactiveAlpha})`);
      scopeGrad.addColorStop(1, `hsla(${reactiveHue}, 100%, ${reactiveLightness}%, 0)`);

      const drawScopeLayer = (gain: number, alpha: number, sampleOffset: number) => {
        ctx.beginPath();
        ctx.globalAlpha = alpha * reactiveAlpha;
        ctx.strokeStyle = scopeGrad;
        ctx.lineWidth = reactiveLineWidth * gain;
        for (let i = 0; i < bufferLength; i++) {
          const t = i / (bufferLength - 1);
          const sampleIndex = (i + sampleOffset) % bufferLength;
          const s = (timeData[sampleIndex] - 128) / 128;
          const x = xStart + t * scopeWidth;
          const y = cy + s * ampBase * gain;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      };

      drawScopeLayer(0.35, 0.55, 0);
      drawScopeLayer(0.65, 0.30, 4);
      drawScopeLayer(0.95, 0.15, 12);

      animationRef.current = requestAnimationFrame(render);
    };

    render();
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
      window.removeEventListener('resize', resize);
    };
  }, [isPlaying, valence, arousal, reservedFooterHeight]);

  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full rounded-2xl pointer-events-none" />;
};

export default LiveVisualizer;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, AlertCircle, Loader2, FileText, Terminal, Key, Activity } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string;
  weights: string;
  advice: string;
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);
  const activeSegmentIndexRef = useRef<number>(-1);

  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;
    if (wavesurfer.current) wavesurfer.current.destroy();
    wsRegions.current = RegionsPlugin.create();
    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(208, 0, 255, 0.2)',
      progressColor: 'rgba(0, 255, 65, 0.5)',
      cursorColor: '#00ff41',
      barWidth: 2,
      barGap: 3,
      height: 120, // Taller rhythm strip for better readability
      plugins: [wsRegions.current],
    });
    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => setCurrentTime(t));
    wavesurfer.current.on('finish', () => setIsPlaying(false));
    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });
    return () => wavesurfer.current?.destroy();
  }, [audioUrl]); 

  useEffect(() => {
    if (!segments.length) return;
    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];
      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);
      if (onSegmentSelect) onSegmentSelect(newEmotion);
    }
  }, [currentTime, segments, onSegmentSelect]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("FILE_TOO_LARGE: MAX 150MB");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);
      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      setCurrentEmotion(null);
    }
  };

  const handleOpenKeyDialog = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;
    const exportData = { trackInfo, segments, suggestions };
    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) { console.error("COPY_FAIL", err); }
  };

  const togglePlay = () => wavesurfer.current && wavesurfer.current.playPause();

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const reader = new FileReader();
      const audioPart = await new Promise<any>((resolve, reject) => {
        reader.onloadend = () => resolve({ inlineData: { data: (reader.result as string).split(',')[1], mimeType: audioFile.type }});
        reader.onerror = reject;
        reader.readAsDataURL(audioFile);
      });

      setAnalysisStep('analyzing_key');
      const trackPrompt = `GLOBAL_TRACK_ANALYSIS: Musical Key, Tempo (BPM), Chord Progression. Return JSON: { "trackInfo": { "key": "str", "tempo": "str", "chords": "str" } }`;
      const trackResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: trackPrompt }] }
      });
      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) { console.warn("PARSE_ERROR_TRACK", e); }

      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `EMO_SEGMENTATION_ANALYSIS: Break into emotional sections. Valence/Arousal (-1.0 to 1.0). ${scriptContext ? `CONTEXT: "${scriptContext}"` : ''} Return JSON: { "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }], "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }] }`;
      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: segmentPrompt }] }
      });
      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);
      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);

      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);
        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.15)`, drag: false, resize: false,
        });
      });
    } catch (err: any) {
      if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
        setError("QUOTA_EXCEEDED");
      } else {
        setError("ANALYSIS_HALTED: " + (err.message || "SIGNAL_LOST"));
      }
    } finally { setAnalysisStep('idle'); }
  };

  return (
    <div className="w-full p-4 md:p-8 max-w-7xl mx-auto text-hackerGreen">
       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-4 space-y-6">
             <div className="terminal-box glass-shine p-6">
                <h3 className="text-sm font-bold mb-6 flex items-center gap-2 uppercase tracking-widest">
                   <Terminal className="w-4 h-4 text-neonViolet" /> INPUT_SOURCE
                </h3>
                <div className="border border-dashed border-neonViolet/50 bg-black/50 rounded-lg p-6 text-center hover:bg-neonViolet/5 transition-all cursor-pointer relative group">
                   <input type="file" accept="audio/*" onChange={handleFileUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                   <Upload className="w-8 h-8 mx-auto text-neonViolet mb-2 group-hover:scale-110 transition-transform" />
                   <p className="text-[10px] hacker-text uppercase tracking-widest">{audioFile ? audioFile.name : "LOAD_WAV_OR_MP3"}</p>
                </div>
                <div className="mt-6">
                  <label className="flex items-center gap-2 text-[9px] hacker-text-dim font-bold uppercase tracking-[0.2em] mb-2">
                    <FileText className="w-3 h-3" /> SCRIPT_METADATA_INJECTOR
                  </label>
                  <textarea
                    className="w-full bg-black/40 border border-neonViolet/30 rounded-lg p-3 text-xs hacker-text placeholder-neonViolet/30 focus:outline-none focus:border-neonViolet transition-colors resize-none h-24"
                    placeholder="ENTER SCENE CONTEXT OR LYRICS..."
                    value={scriptContext}
                    onChange={(e) => setScriptContext(e.target.value)}
                  />
                </div>

                {error === "QUOTA_EXCEEDED" ? (
                  <div className="mt-4 p-4 border border-red-500 bg-red-900/20 rounded flex flex-col gap-3">
                     <div className="flex items-center gap-2">
                       <AlertCircle className="text-red-500 w-4 h-4" />
                       <h4 className="text-red-500 font-bold text-[10px] uppercase">QUOTA_EXCEEDED</h4>
                     </div>
                     <p className="text-[9px] hacker-text-dim">Analysis requires higher throughput. Switch to a paid key.</p>
                     <button 
                       onClick={handleOpenKeyDialog}
                       className="w-full py-2 bg-red-950 border border-red-500 text-red-500 text-[10px] font-bold uppercase tracking-widest animate-pulse"
                     >
                       UPGRADE_KEY
                     </button>
                  </div>
                ) : error && (
                  <div className="mt-4 p-3 bg-red-950/30 border border-red-900 text-[10px] text-red-500 font-bold uppercase">{error}</div>
                )}

                <div className="mt-6 flex gap-2">
                   <button onClick={togglePlay} disabled={!audioFile} className="flex-1 py-2 bg-black border border-neonViolet text-neonViolet text-[10px] font-bold uppercase tracking-widest hover:bg-neonViolet hover:text-black transition-all disabled:opacity-30">
                      {isPlaying ? <Pause className="w-3 h-3 mx-auto" /> : <Play className="w-3 h-3 mx-auto" />}
                   </button>
                   <button onClick={analyzeAudio} disabled={!audioFile || analysisStep !== 'idle'} className="flex-1 py-2 bg-black border border-hackerGreen text-hackerGreen text-[10px] font-bold uppercase tracking-widest hover:bg-hackerGreen hover:text-black transition-all shadow-[0_0_10px_rgba(0,255,65,0.3)] disabled:opacity-30">
                      {analysisStep !== 'idle' ? 'RUNNING...' : 'PROCESS_SIGNAL'}
                   </button>
                </div>
             </div>
             {segments.length > 0 && (
               <div className="terminal-box p-6">
                  <div className="flex items-center justify-between mb-4 pb-2 border-b border-neonViolet/30">
                    <h3 className="text-[10px] font-bold hacker-text-dim uppercase tracking-[0.3em]">TELEMETRY_EXPORT</h3>
