            ctx.lineTo(p.x, p.y);
        }
      }

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = 4 + state.current.bassEnergy * 10 + state.current.beatImpulse * 10;
      ctx.strokeStyle = targetColor;
      ctx.globalAlpha = 0.6 + state.current.beatImpulse * 0.4;
      ctx.stroke();

      // Draw Particle Head
      ctx.beginPath();
      ctx.arc(px, py, 6 + state.current.beatImpulse * 15, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.globalAlpha = 1;
      ctx.shadowColor = targetColor;
      ctx.shadowBlur = 20 + state.current.highEnergy * 20 + state.current.beatImpulse * 40;
      ctx.fill();
      ctx.shadowBlur = 0;

      // --- Layer 3: Resonance Ripples ---
      if (state.current.beatImpulse > 0.5) {
         ctx.beginPath();
         ctx.arc(cx, cy, ORBIT_RADIUS * state.current.radius * (1 + (1-state.current.beatImpulse)*0.5), 0, Math.PI*2);
         ctx.strokeStyle = '#ffffff';
         ctx.lineWidth = 1;
         ctx.globalAlpha = state.current.beatImpulse * 0.4;
         ctx.stroke();
      }

      animationRef.current = requestAnimationFrame(render);
    };

    const handleResize = () => {
        const parent = canvas.parentElement;
        if(parent) {
            canvas.width = parent.clientWidth;
            canvas.height = parent.clientHeight;
        }
    };
    handleResize();
    window.addEventListener('resize', handleResize);

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, targetEmotion]);

  return (
    <div className="relative w-full h-full rounded-2xl overflow-hidden bg-slate-900 shadow-inner">
       <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

       <div className="absolute top-4 left-4 pointer-events-none opacity-50">
          <div className="flex flex-col gap-1">
             <div className="flex items-center gap-2">
                <div className="w-1 h-3 bg-white/20 rounded-full overflow-hidden">
                   <div className="w-full bg-cyan-400 transition-all" style={{ height: `${state.current.tension * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono text-cyan-200">FLUX</span>
             </div>
             <div className="flex items-center gap-2">
                <div className="w-1 h-3 bg-white/20 rounded-full overflow-hidden">
                   <div className="w-full bg-rose-400 transition-all" style={{ height: `${state.current.radius * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono text-rose-200">ENERGY</span>
             </div>
          </div>
       </div>
    </div>
  );
};

export default SoundReactiveMatrix;

import React, { useEffect, useRef } from 'react';
import { EMOTIONAL_KEYS } from '../constants';
import { getNearestKey } from '../utils/emotionMath';
import { EmotionState } from '../types';

interface SoundReactiveMatrixProps {
  mediaElement: HTMLMediaElement | null;
  isPlaying: boolean;
  targetEmotion: EmotionState | null; // The AI-determined "Attractor"
  beatTrigger?: number; // External beat hit timestamp
}

// Physics & Audio Constants
const FFT_SIZE = 2048;
const SMOOTHING = 0.8;
const HISTORY_SIZE = 40; // For trails
const ORBIT_RADIUS = 140; // Base radius of the key circle
const ATTRACTOR_STRENGTH = 0.05; // How strongly the particle is pulled to the active key

const SoundReactiveMatrix: React.FC<SoundReactiveMatrixProps> = ({ mediaElement, isPlaying, targetEmotion, beatTrigger }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // Physics State
  const state = useRef({
    angle: -Math.PI / 2, // Start at Top (C Major)
    radius: 0.5, // 0..1 normalized radius
    velocity: 0,
    tension: 0,
    trail: [] as { x: number; y: number; alpha: number }[],
    beatImpulse: 0,
    bassEnergy: 0,
    midEnergy: 0,
    highEnergy: 0,
    spectralCentroid: 0,
    spectralFlux: 0,
    previousSpectrum: new Float32Array(FFT_SIZE / 2),
  });

  // Pulse when beatTrigger changes
  useEffect(() => {
    if (beatTrigger) {
      state.current.beatImpulse = 1.0;
    }
  }, [beatTrigger]);

  // Initialize Audio
  useEffect(() => {
    if (!mediaElement) return;

    const initAudio = () => {
      if (!audioContextRef.current) {
        const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContext();
      }
      const ctx = audioContextRef.current;

      if (!analyserRef.current) {
        analyserRef.current = ctx.createAnalyser();
        analyserRef.current.fftSize = FFT_SIZE;
        analyserRef.current.smoothingTimeConstant = SMOOTHING;
      }

      if (!sourceRef.current) {
        try {
          const source = ctx.createMediaElementSource(mediaElement);
          source.connect(analyserRef.current);
          analyserRef.current.connect(ctx.destination);
          sourceRef.current = source;
        } catch (e) {
          // Ignore if source already connected
        }
      }
    };
    initAudio();
  }, [mediaElement]);

  // Handle Playback State
  useEffect(() => {
    if (audioContextRef.current && isPlaying && audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  }, [isPlaying]);

  // Main Animation Loop
  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const analyser = analyserRef.current;
    const bufferLength = analyser ? analyser.frequencyBinCount : 0;
    const dataArray = new Uint8Array(bufferLength);
    const floatData = new Float32Array(bufferLength);

    // Audio Feature Extraction Helper
    const extractFeatures = () => {
      if (!analyser) return;
      analyser.getByteFrequencyData(dataArray);
      analyser.getFloatFrequencyData(floatData);

      // 1. Bands
      let bassSum = 0, midSum = 0, highSum = 0;
      const bassLimit = Math.floor(bufferLength * 0.05); // ~0-1kHz
      const midLimit = Math.floor(bufferLength * 0.3);   // ~1-6kHz

      for (let i = 0; i < bufferLength; i++) {
        const val = dataArray[i] / 255.0;
        if (i < bassLimit) bassSum += val;
        else if (i < midLimit) midSum += val;
        else highSum += val;
      }

      state.current.bassEnergy = bassSum / (bassLimit || 1);
      state.current.midEnergy = midSum / (midLimit - bassLimit || 1);
      state.current.highEnergy = highSum / (bufferLength - midLimit || 1);

      // 3. Spectral Flux (Change rate / Tension)
      let flux = 0;
      for (let i = 0; i < bufferLength; i++) {
        const diff = floatData[i] - state.current.previousSpectrum[i];
        if (diff > 0) flux += diff;
        state.current.previousSpectrum[i] = floatData[i];
      }
      state.current.spectralFlux = Math.max(0, flux / 100);

      // 4. Beat Impulse (Internal detection as fallback)
      if (state.current.bassEnergy > 0.6 && state.current.bassEnergy > state.current.beatImpulse + 0.1) {
         state.current.beatImpulse = 1.0;
      }

      state.current.tension = state.current.spectralFlux * 0.5 + state.current.highEnergy * 0.5;
    };

    const render = () => {
      // 1. Update Physics
      if (isPlaying && analyser) extractFeatures();
      else {
        const time = Date.now() / 1000;
        state.current.bassEnergy = 0.2 + Math.sin(time) * 0.05;
        state.current.midEnergy = 0.1;
        state.current.tension = 0.1;
      }

      // Decay impulse
      state.current.beatImpulse *= 0.9;

      let targetAngle = state.current.angle;
      let targetColor = '#ffffff';

      if (targetEmotion) {
        const nearest = getNearestKey(targetEmotion);
        targetAngle = -Math.PI / 2 + (nearest.keyPosition - 1) * (Math.PI / 6);
        targetColor = nearest.primaryColor;
      }

      let diff = targetAngle - state.current.angle;
      while (diff < -Math.PI) diff += Math.PI * 2;
      while (diff > Math.PI) diff -= Math.PI * 2;

      const turbulence = (Math.random() - 0.5) * state.current.tension * 0.1;

      state.current.angle += diff * ATTRACTOR_STRENGTH + turbulence;
      state.current.velocity *= 0.95;

      const targetRadius = 0.3 + (state.current.bassEnergy * 0.4) + (state.current.tension * 0.2);
      state.current.radius += (targetRadius - state.current.radius) * 0.1;

      // 2. Draw
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, width, height);

      // Pre-calculate Particle position for connections
      const pulseMultiplier = 0.6 + state.current.radius * 0.6 + state.current.beatImpulse * 0.2;
      const px = cx + Math.cos(state.current.angle) * (ORBIT_RADIUS * pulseMultiplier);
      const py = cy + Math.sin(state.current.angle) * (ORBIT_RADIUS * pulseMultiplier);

      // --- Layer 1: The Harmonic Ring & Connections ---
      EMOTIONAL_KEYS.forEach((key) => {
        const theta = -Math.PI / 2 + (key.keyPosition - 1) * (Math.PI / 6);
        const x = cx + Math.cos(theta) * ORBIT_RADIUS;
        const y = cy + Math.sin(theta) * ORBIT_RADIUS;

        let angDiff = Math.abs(state.current.angle - theta);
        while(angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI*2);

        const proximity = Math.max(0, 1 - angDiff);
        const activeGlow = proximity * (0.5 + state.current.beatImpulse * 0.5);

        // Enhanced Multi-Pass Glow for Connection Lines
        if (proximity > 0.7) {
          const normProximity = (proximity - 0.7) / 0.3; // 0 to 1 scale
          const baseAlpha = normProximity * (0.15 + state.current.beatImpulse * 0.6);
          const baseWidth = (1 + state.current.beatImpulse * 8) * normProximity;

          const drawConnectionPass = (wFactor: number, aFactor: number, composite: GlobalCompositeOperation) => {
            ctx.save();
            ctx.beginPath();
            ctx.moveTo(px, py);
            ctx.lineTo(x, y);
            ctx.globalAlpha = baseAlpha * aFactor;
            ctx.strokeStyle = key.primaryColor;
            ctx.lineWidth = baseWidth * wFactor;
            ctx.globalCompositeOperation = composite;

            // Add subtle shadow to 'lighter' passes to expand the bloom
            if (composite === 'lighter') {
              ctx.shadowBlur = baseWidth * 2;
              ctx.shadowColor = key.primaryColor;
            }

            ctx.stroke();
            ctx.restore();
          };

          // Bloom Pass 1: Wide soft halo
          drawConnectionPass(4.5, 0.2, 'lighter');
          // Bloom Pass 2: Medium inner glow
          drawConnectionPass(2.2, 0.4, 'lighter');
          // Bloom Pass 3: Dense core line
          drawConnectionPass(1.0, 1.0, 'source-over');
        }

        // Draw Key Node
        ctx.beginPath();
        ctx.arc(x, y, 3 + activeGlow * 8, 0, Math.PI * 2);
        ctx.fillStyle = key.primaryColor;
        ctx.globalAlpha = 0.3 + activeGlow * 0.7;
        ctx.fill();

        if (activeGlow > 0.1) {
            ctx.fillStyle = '#fff';
            ctx.font = '10px Inter';
            ctx.textAlign = 'center';
            ctx.fillText(key.musicalKey.split(' ')[0], x, y + 15);
        }
      });

      // --- Layer 2: The Emotional Particle & Field ---
      state.current.trail.push({ x: px, y: py, alpha: 1.0 });
      if (state.current.trail.length > HISTORY_SIZE) state.current.trail.shift();

      ctx.beginPath();
      if (state.current.trail.length > 0) {
        ctx.moveTo(state.current.trail[0].x, state.current.trail[0].y);
        for (let i = 1; i < state.current.trail.length; i++) {
            const p = state.current.trail[i];
            ctx.lineTo(p.x, p.y);
        }
      }

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = 4 + state.current.bassEnergy * 10 + state.current.beatImpulse * 10;
      ctx.strokeStyle = targetColor;
      ctx.globalAlpha = 0.6 + state.current.beatImpulse * 0.4;
      ctx.stroke();

      // Draw Particle Head
      ctx.beginPath();
      ctx.arc(px, py, 6 + state.current.beatImpulse * 15, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.globalAlpha = 1;
      ctx.shadowColor = targetColor;
      ctx.shadowBlur = 20 + state.current.highEnergy * 20 + state.current.beatImpulse * 40;
      ctx.fill();
      ctx.shadowBlur = 0;

      // --- Layer 3: Resonance Ripples ---
      if (state.current.beatImpulse > 0.5) {
         ctx.beginPath();
         ctx.arc(cx, cy, ORBIT_RADIUS * state.current.radius * (1 + (1-state.current.beatImpulse)*0.5), 0, Math.PI*2);
         ctx.strokeStyle = '#ffffff';
         ctx.lineWidth = 1;
         ctx.globalAlpha = state.current.beatImpulse * 0.4;
         ctx.stroke();
      }

      animationRef.current = requestAnimationFrame(render);
    };

    const handleResize = () => {
        const parent = canvas.parentElement;
        if(parent) {
            canvas.width = parent.clientWidth;
            canvas.height = parent.clientHeight;
        }
    };
    handleResize();
    window.addEventListener('resize', handleResize);

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, targetEmotion]);

  return (
    <div className="relative w-full h-full rounded-2xl overflow-hidden bg-slate-900 shadow-inner">
       <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

       <div className="absolute top-4 left-4 pointer-events-none opacity-50">
          <div className="flex flex-col gap-1">
             <div className="flex items-center gap-2">
                <div className="w-1 h-3 bg-white/20 rounded-full overflow-hidden">
                   <div className="w-full bg-cyan-400 transition-all" style={{ height: `${state.current.tension * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono text-cyan-200">FLUX</span>
             </div>
             <div className="flex items-center gap-2">
                <div className="w-1 h-3 bg-white/20 rounded-full overflow-hidden">
                   <div className="w-full bg-rose-400 transition-all" style={{ height: `${state.current.radius * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono text-rose-200">ENERGY</span>
             </div>
          </div>
       </div>
    </div>
  );
};

export default SoundReactiveMatrix;

import React, { useState, useRef, useEffect } from 'react';
import { Upload, Play, Pause, AlertCircle, Loader2, FileText, Terminal, Key, Activity, Music, Zap, Layers } from 'lucide-react';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { GoogleGenAI } from "@google/genai";
import { EmotionState } from '../types';
import LiveVisualizer from './LiveVisualizer';
import { getNearestKey } from '../utils/emotionMath';

interface AudioSegment {
  startTime: string; // "00:00"
  endTime: string;   // "00:15"
  description: string;
  mood: string;
  valence: number;
  arousal: number;
}

interface TrackInfo {
  key: string;
  tempo: string;
  chords: string;
}

interface ShiftSuggestion {
  target: string;
  weights: string;
  advice: string;
}

interface AppThreeProps {
  onSegmentSelect?: (emotion: EmotionState) => void;
  onBeat?: () => void;
}

type AnalysisStep = 'idle' | 'optimizing' | 'analyzing_key' | 'analyzing_segments';

const AppThree: React.FC<AppThreeProps> = ({ onSegmentSelect, onBeat }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null); 
  const wavesurfer = useRef<WaveSurfer | null>(null);
  const wsRegions = useRef<any>(null);

  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [scriptContext, setScriptContext] = useState('');

  const [isPlaying, setIsPlaying] = useState(false);
  const [analysisStep, setAnalysisStep] = useState<AnalysisStep>('idle');
  const [segments, setSegments] = useState<AudioSegment[]>([]);
  const [trackInfo, setTrackInfo] = useState<TrackInfo | null>(null);
  const [detectedBeats, setDetectedBeats] = useState<number[]>([]);
  const [suggestions, setSuggestions] = useState<ShiftSuggestion[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [copySuccess, setCopySuccess] = useState(false);

  const [currentEmotion, setCurrentEmotion] = useState<EmotionState | null>(null);
  const activeSegmentIndexRef = useRef<number>(-1);
  const lastBeatIndexRef = useRef<number>(-1);

  useEffect(() => {
    if (!containerRef.current || !audioRef.current || !audioUrl) return;
    if (wavesurfer.current) wavesurfer.current.destroy();
    wsRegions.current = RegionsPlugin.create();
    wavesurfer.current = WaveSurfer.create({
      container: containerRef.current,
      media: audioRef.current, 
      waveColor: 'rgba(208, 0, 255, 0.2)',
      progressColor: 'rgba(0, 255, 65, 0.5)',
      cursorColor: '#00ff41',
      barWidth: 2,
      barGap: 3,
      height: 120,
      plugins: [wsRegions.current],
    });
    wavesurfer.current.on('play', () => setIsPlaying(true));
    wavesurfer.current.on('pause', () => setIsPlaying(false));
    wavesurfer.current.on('timeupdate', (t) => setCurrentTime(t));
    wavesurfer.current.on('finish', () => setIsPlaying(false));
    wsRegions.current.on('region-clicked', (region: any, e: MouseEvent) => {
       e.stopPropagation();
       region.play();
    });
    return () => wavesurfer.current?.destroy();
  }, [audioUrl]); 

  // Sync segment selection and beat triggers
  useEffect(() => {
    if (!segments.length) return;
    const currentSegIndex = segments.findIndex(seg => {
      const start = parseTime(seg.startTime);
      const end = parseTime(seg.endTime);
      return currentTime >= start && currentTime < end;
    });
    if (currentSegIndex !== -1 && currentSegIndex !== activeSegmentIndexRef.current) {
      activeSegmentIndexRef.current = currentSegIndex;
      const seg = segments[currentSegIndex];
      const newEmotion = { valence: seg.valence, arousal: seg.arousal };
      setCurrentEmotion(newEmotion);
      if (onSegmentSelect) onSegmentSelect(newEmotion);
    }

    // Local Beat Triggering
    if (detectedBeats.length && onBeat) {
      const currentBeatIndex = detectedBeats.findIndex(b => currentTime >= b && currentTime < b + 0.1);
      if (currentBeatIndex !== -1 && currentBeatIndex !== lastBeatIndexRef.current) {
        lastBeatIndexRef.current = currentBeatIndex;
        onBeat();
      }
    }
  }, [currentTime, segments, detectedBeats, onBeat, onSegmentSelect]);

  const detectBeats = async (file: File) => {
    try {
      const arrayBuffer = await file.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const channelData = audioBuffer.getChannelData(0);
      const sampleRate = audioBuffer.sampleRate;
      const beats: number[] = [];
      const threshold = 0.6; // Energy threshold
      const minInterval = 0.25; // Min 250ms between beats

      let lastBeat = -minInterval;
      // Sampling every 50ms to find peaks
      const step = Math.floor(sampleRate * 0.05);
      for (let i = 0; i < channelData.length; i += step) {
        const time = i / sampleRate;
        const value = Math.abs(channelData[i]);
        if (value > threshold && (time - lastBeat) > minInterval) {
          beats.push(time);
          lastBeat = time;
        }
      }
      setDetectedBeats(beats);
      return beats;
    } catch (e) {
      console.warn("BEAT_DETECTION_FAILED", e);
      return [];
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 150 * 1024 * 1024) {
        setError("FILE_TOO_LARGE: MAX 150MB");
        return;
      }
      if (audioUrl) URL.revokeObjectURL(audioUrl);
      const url = URL.createObjectURL(file);
      setAudioUrl(url);
      setAudioFile(file);
      setSegments([]);
      setTrackInfo(null);
      setSuggestions([]);
      setError(null);
      activeSegmentIndexRef.current = -1;
      lastBeatIndexRef.current = -1;
      setCurrentEmotion(null);

      // Trigger beat detection locally
      await detectBeats(file);
    }
  };

  const handleOpenKeyDialog = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
    }
  };

  const handleCopyData = async () => {
    if (segments.length === 0) return;
    const exportData = { trackInfo, segments, suggestions };
    try {
      await navigator.clipboard.writeText(JSON.stringify(exportData, null, 2));
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) { console.error("COPY_FAIL", err); }
  };

  const togglePlay = () => wavesurfer.current && wavesurfer.current.playPause();

  const parseTime = (timeStr: string) => {
    const parts = timeStr.split(':');
    return parseInt(parts[0]) * 60 + parseFloat(parts[1]);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const analyzeAudio = async () => {
    if (!audioFile) return;
    setAnalysisStep('optimizing');
    setError(null);
    setSegments([]);
    setTrackInfo(null);
    setSuggestions([]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const reader = new FileReader();
      const audioPart = await new Promise<any>((resolve, reject) => {
        reader.onloadend = () => resolve({ inlineData: { data: (reader.result as string).split(',')[1], mimeType: audioFile.type }});
        reader.onerror = reject;
        reader.readAsDataURL(audioFile);
      });

      setAnalysisStep('analyzing_key');
      // Updated prompt to be more specific about chord progressions
      const trackPrompt = `GLOBAL_TRACK_ANALYSIS: Musical Key (e.g., C Major), Tempo (BPM), and the main Chord Progression used in the track. Return JSON: { "trackInfo": { "key": "str", "tempo": "str", "chords": "str" } }`;
      const trackResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: trackPrompt }] }
      });
      try {
        const trackText = trackResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
        const trackData = JSON.parse(trackText);
        if (trackData.trackInfo) setTrackInfo(trackData.trackInfo);
      } catch (e) { console.warn("PARSE_ERROR_TRACK", e); }

      setAnalysisStep('analyzing_segments');
      const segmentPrompt = `EMO_SEGMENTATION_ANALYSIS: Break into emotional sections. Valence/Arousal (-1.0 to 1.0). ${scriptContext ? `CONTEXT: "${scriptContext}"` : ''} Return JSON: { "segments": [{ "startTime": "MM:SS", "endTime": "MM:SS", "description": "str", "mood": "str", "valence": num, "arousal": num }], "suggestions": [{ "target": "str", "weights": "str", "advice": "str" }] }`;
      const segmentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [audioPart, { text: segmentPrompt }] }
      });
      const segmentText = segmentResponse.text.replace(/```json/g, '').replace(/```/g, '').trim();
      const segmentData = JSON.parse(segmentText);
      setSegments(segmentData.segments || []);
      setSuggestions(segmentData.suggestions || []);

      wsRegions.current.clearRegions();
      (segmentData.segments || []).forEach((seg: any, index: number) => {
        const startSeconds = parseTime(seg.startTime);
        const endSeconds = parseTime(seg.endTime);
        const colors = getNearestKey({valence: seg.valence, arousal: seg.arousal});
        const r = parseInt(colors.primaryColor.slice(1, 3), 16);
        const g = parseInt(colors.primaryColor.slice(3, 5), 16);
        const b = parseInt(colors.primaryColor.slice(5, 7), 16);
        wsRegions.current.addRegion({
          start: startSeconds, end: endSeconds, content: `${index + 1}`, 
          color: `rgba(${r}, ${g}, ${b}, 0.15)`, drag: false, resize: false,
        });
      });
    } catch (err: any) {
      if (err.message?.includes('429') || err.message?.includes('RESOURCE_EXHAUSTED')) {
        setError("QUOTA_EXCEEDED");
      } else {
        setError("ANALYSIS_HALTED: " + (err.message || "SIGNAL_LOST"));
      }
    } finally { setAnalysisStep('idle'); }
  };

  return (
