import React, { useEffect, useRef } from 'react';
import { EMOTIONAL_KEYS } from '../constants';
import { getNearestKey } from '../utils/emotionMath';
import { EmotionState } from '../types';

interface SoundReactiveMatrixProps {
  mediaElement: HTMLMediaElement | null;
  isPlaying: boolean;
  targetEmotion: EmotionState | null; // The AI-determined "Attractor"
  beatTrigger?: number; // External beat hit timestamp
}

// Physics & Audio Constants
const FFT_SIZE = 2048;
const SMOOTHING = 0.8;
const HISTORY_SIZE = 40; // For trails
const ORBIT_RADIUS = 140; // Base radius of the key circle
const ATTRACTOR_STRENGTH = 0.05; // How strongly the particle is pulled to the active key

const SoundReactiveMatrix: React.FC<SoundReactiveMatrixProps> = ({ mediaElement, isPlaying, targetEmotion, beatTrigger }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaElementAudioSourceNode | null>(null);

  // Physics State
  const state = useRef({
    angle: -Math.PI / 2, // Start at Top (C Major)
    radius: 0.5, // 0..1 normalized radius
    velocity: 0,
    tension: 0,
    trail: [] as { x: number; y: number; alpha: number }[],
    beatImpulse: 0,
    bassEnergy: 0,
    midEnergy: 0,
    highEnergy: 0,
    spectralCentroid: 0,
    spectralFlux: 0,
    previousSpectrum: new Float32Array(FFT_SIZE / 2),
  });

  // Pulse when beatTrigger changes
  useEffect(() => {
    if (beatTrigger) {
      state.current.beatImpulse = 1.0;
    }
  }, [beatTrigger]);

  // Initialize Audio
  useEffect(() => {
    if (!mediaElement) return;

    const initAudio = () => {
      if (!audioContextRef.current) {
        const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContext();
      }
      const ctx = audioContextRef.current;

      if (!analyserRef.current) {
        analyserRef.current = ctx.createAnalyser();
        analyserRef.current.fftSize = FFT_SIZE;
        analyserRef.current.smoothingTimeConstant = SMOOTHING;
      }

      if (!sourceRef.current) {
        try {
          const source = ctx.createMediaElementSource(mediaElement);
          source.connect(analyserRef.current);
          analyserRef.current.connect(ctx.destination);
          sourceRef.current = source;
        } catch (e) {
          // Ignore if source already connected
        }
      }
    };
    initAudio();
  }, [mediaElement]);

  // Handle Playback State
  useEffect(() => {
    if (audioContextRef.current && isPlaying && audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
  }, [isPlaying]);

  // Main Animation Loop
  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const analyser = analyserRef.current;
    const bufferLength = analyser ? analyser.frequencyBinCount : 0;
    const dataArray = new Uint8Array(bufferLength);
    const floatData = new Float32Array(bufferLength);

    // Audio Feature Extraction Helper
    const extractFeatures = () => {
      if (!analyser) return;
      analyser.getByteFrequencyData(dataArray);
      analyser.getFloatFrequencyData(floatData);

      // 1. Bands
      let bassSum = 0, midSum = 0, highSum = 0;
      const bassLimit = Math.floor(bufferLength * 0.05); // ~0-1kHz
      const midLimit = Math.floor(bufferLength * 0.3);   // ~1-6kHz

      for (let i = 0; i < bufferLength; i++) {
        const val = dataArray[i] / 255.0;
        if (i < bassLimit) bassSum += val;
        else if (i < midLimit) midSum += val;
        else highSum += val;
      }

      state.current.bassEnergy = bassSum / (bassLimit || 1);
      state.current.midEnergy = midSum / (midLimit - bassLimit || 1);
      state.current.highEnergy = highSum / (bufferLength - midLimit || 1);

      // 3. Spectral Flux (Change rate / Tension)
      let flux = 0;
      for (let i = 0; i < bufferLength; i++) {
        const diff = floatData[i] - state.current.previousSpectrum[i];
        if (diff > 0) flux += diff;
        state.current.previousSpectrum[i] = floatData[i];
      }
      state.current.spectralFlux = Math.max(0, flux / 100);

      // 4. Beat Impulse (Internal detection as fallback)
      if (state.current.bassEnergy > 0.6 && state.current.bassEnergy > state.current.beatImpulse + 0.1) {
         state.current.beatImpulse = 1.0;
      }

      state.current.tension = state.current.spectralFlux * 0.5 + state.current.highEnergy * 0.5;
    };

    const render = () => {
      // 1. Update Physics
      if (isPlaying && analyser) extractFeatures();
      else {
        const time = Date.now() / 1000;
        state.current.bassEnergy = 0.2 + Math.sin(time) * 0.05;
        state.current.midEnergy = 0.1;
        state.current.tension = 0.1;
      }

      // Decay impulse
      state.current.beatImpulse *= 0.92;

      let targetAngle = state.current.angle;
      let targetColor = '#ffffff';

      if (targetEmotion) {
        const nearest = getNearestKey(targetEmotion);
        targetAngle = -Math.PI / 2 + (nearest.keyPosition - 1) * (Math.PI / 6);
        targetColor = nearest.primaryColor;
      }

      let diff = targetAngle - state.current.angle;
      while (diff < -Math.PI) diff += Math.PI * 2;
      while (diff > Math.PI) diff -= Math.PI * 2;

      const turbulence = (Math.random() - 0.5) * state.current.tension * 0.15;

      state.current.angle += diff * ATTRACTOR_STRENGTH + turbulence;
      state.current.velocity *= 0.95;

      const targetRadius = 0.3 + (state.current.bassEnergy * 0.4) + (state.current.tension * 0.2);
      state.current.radius += (targetRadius - state.current.radius) * 0.1;

      // 2. Draw
      const width = canvas.width;
      const height = canvas.height;
      const cx = width / 2;
      const cy = height / 2;

      ctx.fillStyle = '#0a0f1d'; // Slightly darker background
      ctx.fillRect(0, 0, width, height);

      // Pre-calculate Particle position for connections
      const pulseMultiplier = 0.6 + state.current.radius * 0.6 + state.current.beatImpulse * 0.15;
      const px = cx + Math.cos(state.current.angle) * (ORBIT_RADIUS * pulseMultiplier);
      const py = cy + Math.sin(state.current.angle) * (ORBIT_RADIUS * pulseMultiplier);

      // --- Layer 1: The Harmonic Ring & Connections ---
      EMOTIONAL_KEYS.forEach((key) => {
        const theta = -Math.PI / 2 + (key.keyPosition - 1) * (Math.PI / 6);
        const x = cx + Math.cos(theta) * ORBIT_RADIUS;
        const y = cy + Math.sin(theta) * ORBIT_RADIUS;

        let angDiff = Math.abs(state.current.angle - theta);
        while(angDiff > Math.PI) angDiff = Math.abs(angDiff - Math.PI*2);

        const proximity = Math.max(0, 1 - angDiff);
        const activeGlow = proximity * (0.5 + state.current.beatImpulse * 0.5);

        // --- HIGH ENERGY BEAM CONNECTION ---
        if (proximity > 0.7) {
          const normProximity = (proximity - 0.7) / 0.3; // 0 to 1 scale
          const baseAlpha = normProximity * (0.2 + state.current.beatImpulse * 0.8);
          // Line width responds aggressively to beat and alignment
          const coreWidth = (1.5 + state.current.beatImpulse * 12) * normProximity;

          const drawConnectionPass = (wFactor: number, aFactor: number, composite: GlobalCompositeOperation, blur: number) => {
            ctx.save();
            ctx.beginPath();

            // Jitter effect on energy spike
            const jitterX = (Math.random() - 0.5) * state.current.beatImpulse * 4;
            const jitterY = (Math.random() - 0.5) * state.current.beatImpulse * 4;

            ctx.moveTo(px + jitterX, py + jitterY);
            ctx.lineTo(x, y);
            ctx.globalAlpha = baseAlpha * aFactor;
            ctx.strokeStyle = key.primaryColor;
            ctx.lineWidth = coreWidth * wFactor;
            ctx.globalCompositeOperation = composite;

            if (blur > 0) {
              ctx.shadowBlur = blur;
              ctx.shadowColor = key.primaryColor;
            }

            ctx.stroke();
            ctx.restore();
          };

          // Bloom Pass 1: Wide Outer Aura
          drawConnectionPass(6.0, 0.15, 'lighter', 15);
          // Bloom Pass 2: Medium Inner Glow
          drawConnectionPass(3.0, 0.3, 'lighter', 5);
          // Bloom Pass 3: White Core Spike (if high beat)
          if (state.current.beatImpulse > 0.4) {
             ctx.save();
             ctx.beginPath();
             ctx.moveTo(px, py);
             ctx.lineTo(x, y);
             ctx.globalAlpha = (state.current.beatImpulse - 0.4) * normProximity;
             ctx.strokeStyle = '#ffffff';
             ctx.lineWidth = coreWidth * 0.3;
             ctx.globalCompositeOperation = 'lighter';
             ctx.stroke();
             ctx.restore();
          }
          // Bloom Pass 4: Solid Semantic Color Line
          drawConnectionPass(1.0, 1.0, 'source-over', 0);
        }

        // Draw Key Node
        ctx.beginPath();
        const nodeSize = 3 + activeGlow * 10 + state.current.beatImpulse * proximity * 5;
        ctx.arc(x, y, nodeSize, 0, Math.PI * 2);
        ctx.fillStyle = key.primaryColor;
        ctx.globalAlpha = 0.3 + activeGlow * 0.7;

        // Node pulse shadow
        if (activeGlow > 0.5) {
            ctx.shadowColor = key.primaryColor;
            ctx.shadowBlur = 15 + state.current.beatImpulse * 30;
        }
        ctx.fill();
        ctx.shadowBlur = 0;

        if (activeGlow > 0.1) {
            ctx.fillStyle = '#fff';
            ctx.font = `bold ${10 + activeGlow * 2}px Inter`;
            ctx.textAlign = 'center';
            ctx.globalAlpha = 0.8;
            ctx.fillText(key.musicalKey.split(' ')[0], x, y + nodeSize + 12);
        }
      });

      // --- Layer 2: The Emotional Particle Trail & Head ---
      state.current.trail.push({ x: px, y: py, alpha: 1.0 });
      if (state.current.trail.length > HISTORY_SIZE) state.current.trail.shift();

      ctx.save();
      ctx.beginPath();
      if (state.current.trail.length > 0) {
        ctx.moveTo(state.current.trail[0].x, state.current.trail[0].y);
        for (let i = 1; i < state.current.trail.length; i++) {
            const p = state.current.trail[i];
            ctx.lineTo(p.x, p.y);
        }
      }

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = 4 + state.current.bassEnergy * 8 + state.current.beatImpulse * 12;
      ctx.strokeStyle = targetColor;
      ctx.globalAlpha = 0.6 + state.current.beatImpulse * 0.4;
      ctx.stroke();
      ctx.restore();

      // Particle Head (Core)
      ctx.save();
      ctx.beginPath();
      const headSize = 7 + state.current.beatImpulse * 18;
      ctx.arc(px, py, headSize, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.globalAlpha = 1;
      ctx.shadowColor = targetColor;
      ctx.shadowBlur = 20 + state.current.highEnergy * 20 + state.current.beatImpulse * 60;
      ctx.fill();

      // Core inner detail
      ctx.beginPath();
      ctx.arc(px, py, headSize * 0.5, 0, Math.PI * 2);
      ctx.fillStyle = targetColor;
      ctx.globalAlpha = 0.5;
      ctx.fill();
      ctx.restore();

      // --- Layer 3: Resonance Ripples ---
      if (state.current.beatImpulse > 0.4) {
         ctx.save();
         ctx.beginPath();
         // Expanding circle
         const rippleR = ORBIT_RADIUS * state.current.radius * (1 + (1 - state.current.beatImpulse) * 1.5);
         ctx.arc(cx, cy, rippleR, 0, Math.PI*2);
         ctx.strokeStyle = targetColor || '#ffffff';
         ctx.lineWidth = 1 + state.current.beatImpulse * 2;
         ctx.globalAlpha = state.current.beatImpulse * 0.4 * (1 - state.current.beatImpulse);
         ctx.stroke();
         ctx.restore();
      }

      animationRef.current = requestAnimationFrame(render);
    };

    const handleResize = () => {
        const parent = canvas.parentElement;
        if(parent) {
            canvas.width = parent.clientWidth;
            canvas.height = parent.clientHeight;
        }
    };
    handleResize();
    window.addEventListener('resize', handleResize);

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [isPlaying, targetEmotion]);

  return (
    <div className="relative w-full h-full rounded-2xl overflow-hidden bg-slate-950 shadow-inner">
       <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

       <div className="absolute top-4 left-4 pointer-events-none opacity-60">
          <div className="flex flex-col gap-1.5">
             <div className="flex items-center gap-2">
                <div className="w-1.5 h-4 bg-white/10 rounded-full overflow-hidden border border-white/5">
                   <div className="w-full bg-cyan-400 shadow-[0_0_5px_#22d3ee] transition-all" style={{ height: `${state.current.tension * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono font-bold text-cyan-200 tracking-tighter">FLUX</span>
             </div>
             <div className="flex items-center gap-2">
                <div className="w-1.5 h-4 bg-white/10 rounded-full overflow-hidden border border-white/5">
                   <div className="w-full bg-rose-400 shadow-[0_0_5px_#fb7185] transition-all" style={{ height: `${state.current.radius * 100}%`, marginTop: 'auto' }}></div>
                </div>
                <span className="text-[10px] font-mono font-bold text-rose-200 tracking-tighter">ENERGY</span>
             </div>
          </div>
       </div>
    </div>
  );
};

